    public static boolean preloadProvinceCache() {
        provCacheLoaded = false;
        provCache = null;
        int numProvinces = CFG.map.getMapNumOfProvinces(CFG.map.getActiveMapIDN());
        String cachePath = "map/" + CFG.map.getFileActiveMapPath() + "data/provinces_cache";
        FileHandle cacheFile = FileManager.loadFile(cachePath);

        if (cacheFile.exists()) {
            java.io.DataInputStream dis = null;
            try {
                byte[] cacheData = cacheFile.readBytes();
                dis = new java.io.DataInputStream(new java.io.ByteArrayInputStream(cacheData));
                int cachedCount = dis.readInt();
                if (cachedCount == numProvinces) {
                    provCache = new Province_GameData2[numProvinces];
                    for (int i = 0; i < numProvinces; ++i) {
                        boolean hasFullData = dis.readBoolean();
                        if (hasFullData) {
                            provCache[i] = readProvinceDataFast(dis);
                        } else {
                            int pxLen = dis.readInt();
                            if (pxLen > 0) { dis.skipBytes(pxLen * 2); }
                            int pyLen = dis.readInt();
                            if (pyLen > 0) { dis.skipBytes(pyLen * 2); }
                        }
                    }
                    dis.close();
                    provCacheLoaded = true;
                    return true;
                }
                dis.close();
            } catch (Exception e) {
                provCache = null;
                if (CFG.LOGs) CFG.exceptionStack(e);
            } finally {
                if (dis != null) try { dis.close(); } catch (Exception e) {}
            }
        }

        generateProvinceCache(numProvinces, cachePath);

        cacheFile = FileManager.loadFile(cachePath);
        if (cacheFile.exists()) {
            java.io.DataInputStream dis = null;
            try {
                byte[] cacheData = cacheFile.readBytes();
                dis = new java.io.DataInputStream(new java.io.ByteArrayInputStream(cacheData));
                int cachedCount = dis.readInt();
                if (cachedCount == numProvinces) {
                    provCache = new Province_GameData2[numProvinces];
                    for (int i = 0; i < numProvinces; ++i) {
                        boolean hasFullData = dis.readBoolean();
                        if (hasFullData) {
                            provCache[i] = readProvinceDataFast(dis);
                        } else {
                            int pxLen = dis.readInt();
                            if (pxLen > 0) { dis.skipBytes(pxLen * 2); }
                            int pyLen = dis.readInt();
                            if (pyLen > 0) { dis.skipBytes(pyLen * 2); }
                        }
                    }
                    dis.close();
                    provCacheLoaded = true;
                    return true;
                }
                dis.close();
            } catch (Exception e) {
                provCache = null;
                if (CFG.LOGs) CFG.exceptionStack(e);
            } finally {
                if (dis != null) try { dis.close(); } catch (Exception e) {}
            }
        }
        return false;
    }

    private static void generateProvinceCache(int numProvinces, String cachePath) {
        final Province_GameData2[] gdArray = new Province_GameData2[numProvinces];
        final boolean[] usedFallback = new boolean[numProvinces];
        final String baseDataPath = "map/" + CFG.map.getFileActiveMapPath() + "data/" + "provinces/";
        final String baseUpdatePath = "map/" + CFG.map.getFileActiveMapPath() + "update/";
        java.util.concurrent.CountDownLatch latch = new java.util.concurrent.CountDownLatch(numProvinces);

        for (int i = 0; i < numProvinces; ++i) {
            final int provinceID = i;
            EXECUTOR.execute(() -> {
                try {
                    FileHandle f = FileManager.loadFile(baseDataPath + provinceID);
                    try {
                        gdArray[provinceID] = (Province_GameData2)CFG.deserialize(f.readBytes());
                    } catch (Exception e) {
                        try {
                            FileHandle uf = FileManager.loadFile(baseUpdatePath + provinceID);
                            String text = uf.readString();
                            int semi = text.indexOf(';');
                            String xs = semi >= 0 ? text.substring(0, semi) : "";
                            String ys = semi >= 0 ? text.substring(semi + 1) : "";
                            int count = 0;
                            int idx = 0, n;
                            while ((n = xs.indexOf(',', idx)) >= 0) { count++; idx = n + 1; }
                            if (xs.length() > 0) count++;
                            ArrayList<Short> px = new ArrayList<Short>(count);
                            ArrayList<Short> py = new ArrayList<Short>(count);
                            idx = 0;
                            for (int j = 0; j < count; ++j) {
                                n = xs.indexOf(',', idx);
                                px.add((short)Integer.parseInt(n >= 0 ? xs.substring(idx, n) : xs.substring(idx)));
                                idx = n + 1;
                            }
                            idx = 0;
                            for (int j = 0; j < count; ++j) {
                                n = ys.indexOf(',', idx);
                                py.add((short)Integer.parseInt(n >= 0 ? ys.substring(idx, n) : ys.substring(idx)));
                                idx = n + 1;
                            }
                            gdArray[provinceID] = new Province_GameData2(-1, px, py, null, new ArrayList<Short>(), new ArrayList<Short>());
                            usedFallback[provinceID] = true;
                        } catch (Exception e2) {
                            usedFallback[provinceID] = true;
                        }
                    }
                } catch (Exception e) {
                    usedFallback[provinceID] = true;
                } finally {
                    latch.countDown();
                }
            });
        }

        try { latch.await(); } catch (InterruptedException e) { CFG.exceptionStack(e); }

        try {
            java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream(numProvinces * 1024);
            java.io.DataOutputStream dos = new java.io.DataOutputStream(baos);
            dos.writeInt(numProvinces);
            for (int i = 0; i < numProvinces; ++i) {
                Province_GameData2 gd = gdArray[i];
                if (gd == null || usedFallback[i]) {
                    dos.writeBoolean(false);
                    dos.writeInt(0);
                    dos.writeInt(0);
                } else {
                    dos.writeBoolean(true);
                    writeProvinceDataFast(dos, gd);
                }
            }
            dos.close();
            FileManager.getSaveType(cachePath).writeBytes(baos.toByteArray(), false);
        } catch (Exception e) { if (CFG.LOGs) CFG.exceptionStack(e); }
    }

    public static void clearProvCache() {
        provCache = null;
        provCacheLoaded = false;
    }
