    public int isInvestForeignGold(int provinceID) {
        for (int i = this.investForeignGold.size() - 1; i >= 0; --i) {
            if (this.investForeignGold.get((int)i).provinceID != provinceID) continue;
            return this.investForeignGold.get((int)i).returnTurnID - GameCalendar.TURNID;
        }
        return -1;
    }

    public int isBuildForeignGold(int provinceID) {
        for (int i = this.buildForeignGold.size() - 1; i >= 0; --i) {
            if (this.buildForeignGold.get((int)i).provinceID != provinceID) continue;
            return this.buildForeignGold.get((int)i).returnTurnID - GameCalendar.TURNID;
        }
        return -1;
    }

    public void cleanForeignInvestmentBuild() {
        this.investForeignGold.clear();
        this.buildForeignGold.clear();
    }

    public final void reverseWasteland() {
        for (int i = 0; i < this.iProvincesSize; ++i) {
            if (this.getProv(i).getSeaProv()) continue;
            if (this.getProv(i).getWastelandLvl() >= 0) {
                this.getProv(i).setWastelandLvl(-1);
            } else {
                this.getProv(i).setWastelandLvl(0);
            }
        }
    }

    public final void addPropaganda(Propaganda nPropaganda) {
        for (int i = this.propaganda.size() - 1; i >= 0; --i) {
            if (this.propaganda.get((int)i).provinceID != nPropaganda.provinceID) continue;
            this.propaganda.get((int)i).endTurnID += Math.max(0, nPropaganda.endTurnID - GameCalendar.TURNID);
            return;
        }
        this.propaganda.add(nPropaganda);
    }

    public int isPropagandaOrganized(int provinceID) {
        for (int i = this.propaganda.size() - 1; i >= 0; --i) {
            if (this.propaganda.get((int)i).provinceID != provinceID) continue;
            return this.propaganda.get((int)i).endTurnID - GameCalendar.TURNID;
        }
        return -1;
    }

    public void clearPropaganda() {
        this.propaganda.clear();
    }

