    public static AMR RNDAR(int provinceID) {
        int limit = Math.max(0, CFG.gameAction.gMARY(provinceID, CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()));
        int units = (int)((float)limit * GameValues.gvArmyRecruit.RECRUIT_ARMY_DEFAULT_SLIDER_PERC_OF_MAX);
        return new AMR(provinceID, units, limit);
    }

