    public static boolean checkUncivilizedMenu(int nProvinceID) {
        return CFG.ideologiesMgr.getIdeologyID((int)CFG.core.getCiv((int)CFG.core.getPlayer((int)CFG.PLAYER_TURN_ID).getCivId()).getIdeology()).CAN_BECOME_CIVILIZED >= 0 && CFG.core.getProv(nProvinceID).getCivId() == 0 && Core.uncivilizedProvinceBordersWithCiv(nProvinceID, CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId());
    }

    public static boolean uncivilizedProvinceBordersWithCiv(int nProvinceID, int nCivID) {
        if (nProvinceID >= 0) {
            for (int i = 0; i < CFG.core.getProv(nProvinceID).getNeighProvincesSize(); ++i) {
                if (CFG.core.getProv(CFG.core.getProv(nProvinceID).getNeighProvinces(i)).getCivId() != nCivID) continue;
                return true;
            }
        }
        return false;
    }

    public int uncivilizedCanMigrate_FromProvince_NumOfTurns(int nProvinceID, int nCivID) {
        try {
            return Math.max(1, GameValues.gvMigrate.CAN_MIGRATE_EVERY_X_TURNS - CFG.core.getProv(CFG.core.getActiveProvID()).getCores().getNumOfOwnership(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()));
        }
        catch (Exception ex) {
            return 1;
        }
    }

    public static boolean uncivilizedCanMigrate_FromProv(int nProvinceID, int nCivID) {
        if (nProvinceID >= 0 && !CFG.core.getProv(nProvinceID).isOccupied() && CFG.core.getProv(nProvinceID).getCivId() == nCivID) {
            boolean bordersWithNeutralProvince = false;
            for (int i = 0; i < CFG.core.getProv(nProvinceID).getNeighProvincesSize(); ++i) {
                if (CFG.core.getProv(CFG.core.getProv(nProvinceID).getNeighProvinces(i)).getCivId() != 0 || CFG.core.getProv(CFG.core.getProv(nProvinceID).getNeighProvinces(i)).getWastelandLvl() >= 0) continue;
                bordersWithNeutralProvince = true;
                break;
            }
            if (!bordersWithNeutralProvince) {
                return false;
            }
            return CFG.core.getProv(nProvinceID).getCores().getNumOfOwnership(nCivID) >= GameValues.gvMigrate.CAN_MIGRATE_EVERY_X_TURNS;
        }
        return false;
    }

    public static boolean uncivilizedCanMigrate(int nProvinceID, int nCivID) {
        if (nProvinceID >= 0) {
            if (CFG.core.getProv(nProvinceID).getSeaProv() || CFG.core.getProv(nProvinceID).getWastelandLvl() >= 0 || CFG.core.getProv(nProvinceID).getCivId() > 0) {
                return false;
            }
            for (int i = 0; i < CFG.core.getProv(nProvinceID).getNeighProvincesSize(); ++i) {
                if (CFG.core.getProv(CFG.core.getProv(nProvinceID).getNeighProvinces(i)).getCivId() != nCivID) continue;
                return true;
            }
        }
        return false;
    }

    public static boolean uncivilizedCanFishing(int nProvinceID) {
        if (nProvinceID >= 0) {
            return CFG.core.getProv(nProvinceID).getSeaProv();
        }
        return false;
    }

    public static boolean provinceBordersWithProvince_LandByLand(int iA, int iB_bordersWithA) {
        for (int i = 0; i < CFG.core.getProv(iA).getNeighProvincesSize(); ++i) {
            if (CFG.core.getProv(iA).getNeighProvinces(i) != iB_bordersWithA) continue;
            return true;
        }
        return false;
    }

