    private boolean loadProvincesFast(FileHandle cacheFile, int numProvinces) {
        try {
            byte[] cacheData = cacheFile.readBytes();
            java.io.DataInputStream dis = new java.io.DataInputStream(new java.io.ByteArrayInputStream(cacheData));
            int cachedCount = dis.readInt();
            if (cachedCount != numProvinces) { dis.close(); return false; }
            for (int i = 0; i < numProvinces; ++i) {
                boolean hasFullData = dis.readBoolean();
                if (hasFullData) {
                    Province_GameData2 gd = readProvinceDataFast(dis);
                    this.lProvs.set(i, new Province(i, gd));
                } else {
                    int pxLen = dis.readInt();
                    if (pxLen <= 0) { this.build_LoadProvince_ThreadSafe(i); continue; }
                    ArrayList<Short> px = new ArrayList<Short>(pxLen);
                    for (int j = 0; j < pxLen; ++j) px.add(dis.readShort());
                    int pyLen = dis.readInt();
                    ArrayList<Short> py = new ArrayList<Short>(pyLen);
                    for (int j = 0; j < pyLen; ++j) py.add(dis.readShort());
                    this.lProvs.set(i, new Province(i, new Province_GameData2(-1, px, py, null, new ArrayList<Short>(), new ArrayList<Short>())));
                }
            }
            dis.close();
            this.updateProvincesSize();
            return true;
        } catch (java.io.IOException e) {
            if (CFG.LOGs) CFG.exceptionStack(e);
            return false;
        }
    }

    private static void writeShortList(java.io.DataOutputStream dos, List<Short> list) throws java.io.IOException {
        if (list == null) { dos.writeInt(-1); return; }
        dos.writeInt(list.size());
        for (int i = 0; i < list.size(); ++i) dos.writeShort(list.get(i));
    }

    private static List<Short> readShortList(java.io.DataInputStream dis) throws java.io.IOException {
        int size = dis.readInt();
        if (size < 0) return null;
        ArrayList<Short> list = new ArrayList<Short>(size);
        for (int i = 0; i < size; ++i) list.add(dis.readShort());
        return list;
    }

    private static void writeProvinceDataFast(java.io.DataOutputStream dos, Province_GameData2 gd) throws java.io.IOException {
        writeShortList(dos, gd.lPointsX);
        writeShortList(dos, gd.lPointsY);
        dos.writeInt(gd.iLevelOfPort);
        if (gd.lProvinceBorder == null) {
            dos.writeInt(-1);
        } else {
            dos.writeInt(gd.lProvinceBorder.size());
            for (int i = 0; i < gd.lProvinceBorder.size(); ++i) {
                Province_Border_GameData b = gd.lProvinceBorder.get(i);
                dos.writeInt(b.getWithProvinceID());
                writeShortList(dos, b.getPointsX());
                writeShortList(dos, b.getPointsY());
            }
        }
        writeShortList(dos, gd.lNeighboringProvinces);
        writeShortList(dos, gd.lNeighboringSeaProvinces);
        Province_Info_GameData3 info = gd.provinceInfo;
        dos.writeFloat(info.fGrowthRate);
        dos.writeUTF(info.sTerrainTAG == null ? "" : info.sTerrainTAG);
        dos.writeInt(info.iContinentID);
        dos.writeInt(info.iRegionID);
        dos.writeInt(info.iShiftX);
        dos.writeInt(info.iShiftY);
        dos.writeInt(gd.iPort_ShiftX);
        dos.writeInt(gd.iPort_ShiftY);
    }

    private static Province_GameData2 readProvinceDataFast(java.io.DataInputStream dis) throws java.io.IOException {
        Province_GameData2 gd = new Province_GameData2();
        gd.lPointsX = readShortList(dis);
        gd.lPointsY = readShortList(dis);
        gd.iLevelOfPort = dis.readInt();
        int borderSize = dis.readInt();
        if (borderSize >= 0) {
            gd.lProvinceBorder = new ArrayList<Province_Border_GameData>(borderSize);
            for (int i = 0; i < borderSize; ++i) {
                int withId = dis.readInt();
                List<Short> bx = readShortList(dis);
                List<Short> by = readShortList(dis);
                gd.lProvinceBorder.add(new Province_Border_GameData(withId, bx, by));
            }
        }
        gd.lNeighboringProvinces = readShortList(dis);
        gd.lNeighboringSeaProvinces = readShortList(dis);
        gd.provinceInfo.fGrowthRate = dis.readFloat();
        gd.provinceInfo.sTerrainTAG = dis.readUTF();
        gd.provinceInfo.iContinentID = dis.readInt();
        gd.provinceInfo.iRegionID = dis.readInt();
        gd.provinceInfo.iShiftX = dis.readInt();
        gd.provinceInfo.iShiftY = dis.readInt();
        gd.iPort_ShiftX = dis.readInt();
        gd.iPort_ShiftY = dis.readInt();
        return gd;
    }

    private final void build_LoadProvince_ThreadSafe(int i) {
        FileHandle file = FileManager.loadFile("map/" + CFG.map.getFileActiveMapPath() + "update/" + i);
        String text = file.readString();
        int semiPos = text.indexOf(';');
        String xs = semiPos >= 0 ? text.substring(0, semiPos) : text;
        String ys = semiPos >= 0 ? text.substring(semiPos + 1) : "";
        int count = 0;
        int idx = 0;
        int next;
        while ((next = xs.indexOf(',', idx)) >= 0) { count++; idx = next + 1; }
        if (xs.length() > 0) count++;
        ArrayList<Short> tempPointsX = new ArrayList<Short>(count);
        ArrayList<Short> tempPointsY = new ArrayList<Short>(count);
        idx = 0;
        for (int j = 0; j < count; ++j) {
            next = xs.indexOf(',', idx);
            String sx = next >= 0 ? xs.substring(idx, next) : xs.substring(idx);
            tempPointsX.add((short)Integer.parseInt(sx));
            idx = next + 1;
        }
        idx = 0;
        for (int j = 0; j < count; ++j) {
            next = ys.indexOf(',', idx);
            String sy = next >= 0 ? ys.substring(idx, next) : ys.substring(idx);
            tempPointsY.add((short)Integer.parseInt(sy));
            idx = next + 1;
        }
        this.lProvs.set(i, new Province(i, new Province_GameData2(-1, tempPointsX, tempPointsY, null, new ArrayList<Short>(), new ArrayList<Short>())));
    }

