    public final void buildBasinsOfSeaProvinces() {
        for (int i = 0; i < this.getProvinSize(); ++i) {
            this.getProv(i).setBasin(-1);
        }
        CFG.map.numOfBasins = 0;
        int currBasin = 0;
        ArrayList<Integer> recentlyAdded = new ArrayList<Integer>();
        ArrayList<Integer> currProvinces = new ArrayList<Integer>();
        for (int p = 0; p < this.getProvinSize(); ++p) {
            if (!this.getProv(p).getSeaProv() || this.getProv(p).getBasinID() >= 0) continue;
            this.getProv(p).setBasin(currBasin);
            recentlyAdded.add(p);
            while (recentlyAdded.size() > 0) {
                int a;
                currProvinces.clear();
                for (a = recentlyAdded.size() - 1; a >= 0; --a) {
                    boolean wasntAdded = true;
                    for (int j = currProvinces.size() - 1; j >= 0; --j) {
                        if (currProvinces.get(j) != recentlyAdded.get(a)) continue;
                        wasntAdded = false;
                        break;
                    }
                    if (!wasntAdded) continue;
                    currProvinces.add((Integer)recentlyAdded.get(a));
                }
                recentlyAdded.clear();
                for (a = currProvinces.size() - 1; a >= 0; --a) {
                    for (int i = 0; i < CFG.core.getProv((Integer)currProvinces.get(a)).getNeighProvincesSize(); ++i) {
                        if (!CFG.core.getProv(CFG.core.getProv((Integer)currProvinces.get(a)).getNeighProvinces(i)).getSeaProv() || CFG.core.getProv(CFG.core.getProv((Integer)currProvinces.get(a)).getNeighProvinces(i)).getBasinID() >= 0) continue;
                        CFG.core.getProv(CFG.core.getProv((Integer)currProvinces.get(a)).getNeighProvinces(i)).setBasin(currBasin);
                        recentlyAdded.add(CFG.core.getProv((Integer)currProvinces.get(a)).getNeighProvinces(i));
                    }
                }
            }
            ++currBasin;
            recentlyAdded.clear();
            currProvinces.clear();
        }
        CFG.map.numOfBasins = currBasin;
    }

    public final void loadRegions() {
        int i;
        this.lRegions.clear();
        this.iRegionsSize = 0;
        FileHandle file = FileManager.loadFile("map/" + CFG.map.getFileActiveMapPath() + "data/" + "regions");
        String text = file.readString();
        String[] sAllRegions = text.split("\n");
        ArrayList<Boolean> tempAdded = new ArrayList<Boolean>();
        for (i = 0; i < CFG.core.getProvinSize(); ++i) {
            tempAdded.add(false);
        }
        for (i = 0; i < sAllRegions.length; ++i) {
            int j;
            String[] sRegion = sAllRegions[i].split(";");
            Region newRegion = new Region();
            for (j = 0; j < sRegion.length; ++j) {
                newRegion.addProvince(Integer.parseInt(sRegion[j]));
            }
            for (j = 0; j < sRegion.length; ++j) {
                tempAdded.set(newRegion.getProvince(j), true);
            }
            this.lRegions.add(newRegion);
            this.lRegions.get(i).buildRegionBounds();
        }
        Images.mainMenuEdge2 = Core.getGL();
        Region tempRegionOfProvincesWithoutIDs = new Region();
        for (int i2 = 0; i2 < CFG.core.getProvinSize(); ++i2) {
            if (((Boolean)tempAdded.get(i2)).booleanValue()) continue;
            tempRegionOfProvincesWithoutIDs.addProvince(i2);
        }
        if (tempRegionOfProvincesWithoutIDs.getProvincesSize2() > 0) {
            this.lRegions.add(tempRegionOfProvincesWithoutIDs);
            this.lRegions.get(this.lRegions.size() - 1).buildRegionBounds();
        }
        this.iRegionsSize = this.lRegions.size();
    }

