    private final PreDefined_Borders_Data_GameData build_PreDefinedCivsBorders_CivData(int nCivID) {
        PreDefined_Borders_Data_GameData tempBorders = new PreDefined_Borders_Data_GameData();
        tempBorders.setCapitalProvinceID(this.getCiv(nCivID).getCapitalProvID());
        for (int i = 0; i < this.getCiv(nCivID).getNumOfProvs(); ++i) {
            tempBorders.addProvinceID(this.getCiv(nCivID).getProvID(i));
        }
        return tempBorders;
    }

    public int getCapitalOrProvince(int civID) {
        if (CFG.core.getCiv(civID).getCapitalProvID() >= 0 && CFG.core.getProv(CFG.core.getCiv(civID).getCapitalProvID()).getCivId() == civID) {
            return CFG.core.getCiv(civID).getCapitalProvID();
        }
        if (CFG.core.getCiv(civID).getNumOfProvs() > 0) {
            return CFG.core.getCiv(civID).getProvID(0);
        }
        return -1;
    }

