    public final void build_SuggestedOwners(int nScenarioID) {
        CFG.core.setScenarioID(nScenarioID);
        CFG.core.loadScenario(true);
        for (int i = 1; i < this.getCivsSize(); ++i) {
            if (this.getCiv(i).getCapitalProvID() < 0 || this.getCiv(i).getCivTag().equals("ran") || CFG.ideologiesMgr.REBELS_ID == CFG.ideologiesMgr.getIdeologyID(this.getCiv(i).getCivTag())) continue;
            try {
                int k;
                FileHandle file = FileManager.loadFile("map/" + CFG.map.getFileActiveMapPath() + "suggested_owners/" + this.getCiv(i).getCapitalProvID());
                String sOwners = file.readString();
                String[] sRes = sOwners.split(";");
                boolean bAdd = true;
                boolean updateDate = false;
                for (int j = 0; j < sRes.length; j += 2) {
                    if (!sRes[j].equals(this.getCiv(i).getCivTag())) continue;
                    bAdd = false;
                    if (GameCalendar.currYear >= Integer.parseInt(sRes[j + 1])) break;
                    updateDate = true;
                    sRes[j + 1] = "" + GameCalendar.currYear;
                    break;
                }
                if (bAdd) {
                    FileHandle fileSaveSuggestedOwners = FileManager.getSaveType("map/" + CFG.map.getFileActiveMapPath() + "suggested_owners/" + this.getCiv(i).getCapitalProvID());
                    fileSaveSuggestedOwners.writeString(sRes[0] + ";", false);
                    for (k = 1; k < sRes.length; ++k) {
                        fileSaveSuggestedOwners.writeString(sRes[k] + ";", true);
                    }
                    fileSaveSuggestedOwners.writeString(this.getCiv(i).getCivTag() + ";" + GameCalendar.currYear + ";", true);
                    continue;
                }
                if (!updateDate) continue;
                FileHandle fileSaveSuggestedOwners = FileManager.getSaveType("map/" + CFG.map.getFileActiveMapPath() + "suggested_owners/" + this.getCiv(i).getCapitalProvID());
                fileSaveSuggestedOwners.writeString(sRes[0] + ";", false);
                for (k = 1; k < sRes.length; ++k) {
                    fileSaveSuggestedOwners.writeString(sRes[k] + ";", true);
                }
                continue;
            }
            catch (GdxRuntimeException ex) {
                FileHandle fileSaveSuggestedOwners = FileManager.getSaveType("map/" + CFG.map.getFileActiveMapPath() + "suggested_owners/" + this.getCiv(i).getCapitalProvID());
                fileSaveSuggestedOwners.writeString(this.getCiv(i).getCivTag() + ";" + GameCalendar.currYear + ";", false);
            }
        }
        CFG.toastM.addM(CFG.lang.get("Done") + " #" + CFG.lang.get(CFG.core.getGameScenars().getScenarioNameID(nScenarioID)), CFG.COLOR_HOVER_TITLE);
    }

