    public final void loadScenario(boolean nEditor) {
        int i;
        this.disposeCivilizations();
        this.lCivs = this.gameScenarios.loadCivilizations(nEditor);
        this.iCivsSize = this.lCivs.size();
        this.iAvailableCivilizations = this.iCivsSize - 1;
        this.loadScenario_2_Flags();
        GameCalendar.TURNID = 1;
        CFG.PLAYER_TURN_ID = 0;
        GameCalendar.currDay = this.getGameScenars().getScenarioDay(this.getScenarioID());
        GameCalendar.currMonth = this.getGameScenars().getScenarioMonth(this.getScenarioID());
        GameCalendar.currYear = this.getGameScenars().getScenarioYearID(this.getScenarioID());
        GameCalendar.CURRENT_AGEID = CFG.gameAges.getAgeOfYear(GameCalendar.currYear);
        VictoryManager.VICTORY_CONTROL_PROVINCES_PERC = 100;
        VictoryManager.VICTORY_LIMIT_OF_TURNS = 0;
        VictoryManager.VICTORY_TECHNOLOGY = VictoryManager.getDefault_VictoryTechnology();
        for (i = 0; i < this.getProvinSize(); ++i) {
            for (int j = 0; j < this.getProv(i).getProvinceBordersLandByLandSize(); ++j) {
                this.getProv(i).getProvBordersLandByLand().get(j).setIsCivilizationBorder(this.getProv(i).getCivId() != this.getProv(this.getProv(i).getProvBordersLandByLand().get(j).getWithProvinceID()).getCivId(), i);
            }
            if (this.getProv(i).getCivId() <= 0) continue;
            this.getCiv(this.getProv(i).getCivId()).addProv_Just(i);
        }
        if (nEditor) {
            int numOfRandomCivs = 1;
            for (i = 1; i < this.getCivsSize(); ++i) {
                if (!this.getCiv(i).getCivTag().equals("ran")) continue;
                this.randomCivilizationColor(i);
                this.getCiv(i).setCivName(this.getCiv(i).getCivName() + " " + numOfRandomCivs++);
            }
        }
        this.getGameScenars().loadProvincesData(nEditor);
        this.getGameScenars().loadEventsData();
        this.buildWastelandLevels();
        this.getGameScenars().loadDiplomacyData(nEditor);
        CFG.hreMgr.loadHolyRomanEmpire_ScenarioData();
        this.buildLeaders();
        this.buildCivilizationsRegions();
        this.buildCivilizationsRegions_TextOver();
        if (this.getGameScenars().getScenario_ActivePallet_TAG() != null) {
            for (i = 0; i < CFG.palletManager.getNumOfPallets(); ++i) {
                if (!CFG.palletManager.getPalletTag(i).equals(this.getGameScenars().getScenario_ActivePallet_TAG())) continue;
                CFG.palletManager.setActivePalletID(i + 1);
                CFG.palletManager.loadCivilizationsPaletteOfColors(CFG.palletManager.getActivePalletID());
                break;
            }
        }
        CitiesManager.buildLevelsOfCities();
        CFG.gameAction.buildRank_Score();
        CFG.menus.updateCreateNewGame_Top();
        CFG.disposeActiveCivFlagD();
        this.updateActiveProvinceBorder_Style();
    }

