    private final void disposeCivilizations() {
        if (this.lCivs != null) {
            int i;
            try {
                for (i = 0; i < this.iCivsSize; ++i) {
                    try {
                        this.getCiv(i).getFlagC().dispose();
                        continue;
                    }
                    catch (Exception ex) {
                        CFG.exceptionStack(ex);
                    }
                }
            }
            catch (Exception ex) {
                CFG.exceptionStack(ex);
            }
            for (i = 0; i < this.getProvinSize(); ++i) {
                this.getProv(i).setCivId_LoadScenario(0);
                this.getProv(i).setWastelandLvl(-1);
                this.getProv(i).setIsCapital(false);
                this.getProv(i).setRevRisk(0.0f);
                this.getProv(i).setLvlOfFarm(0);
                this.getProv(i).setLvlOfFort(0);
                this.getProv(i).setLvlOfWatchTower(0);
                this.getProv(i).setLvlOfSupply(0);
                this.getProv(i).setLvlOfWorkshop(0);
                this.getProv(i).setLvlOfLibrary(0);
                this.getProv(i).setLvlOfArmoury(0);
                this.getProv(i).setLvlOfMarket(0);
                if (this.getProv(i).getLvlOfPort() <= 0) continue;
                this.getProv(i).setLvlOfPort(0);
            }
            this.lAlliances.clear();
            this.iAlliancesSize = 0;
            this.lWars.clear();
            this.iWarsSize = 0;
            this.lPeaceTreaties.clear();
            CFG.plagueManager.plaguesActive.clear();
            this.investForeignGold.clear();
            this.buildForeignGold.clear();
            this.propaganda.clear();
            this.diplomaticSummits.clear();
            this.diplomaticSummitCooldowns.clear();
            this.lActive_CivRegion.clear();
            this.setActiveProvID(-1);
        }
    }

