    public final void shuffleCivilizations() {
        int i;
        CFG.core.disableDrawCivlizationsRegions_Players();
        ArrayList<Boolean> lTaken = new ArrayList<Boolean>();
        ArrayList<Integer> lTakeProvinceOfCivID = new ArrayList<Integer>();
        for (int i2 = 1; i2 < this.getCivsSize(); ++i2) {
            lTaken.add(false);
        }
        while (lTakeProvinceOfCivID.size() != this.getCivsSize() - 1) {
            int nID;
            while (((Boolean)lTaken.get((nID = CFG.oR.nextInt(this.getCivsSize() - 1) + 1) - 1)).booleanValue()) {
            }
            lTaken.set(nID - 1, true);
            lTakeProvinceOfCivID.add(nID);
        }
        ArrayList tempOwners = new ArrayList();
        ArrayList<Integer> tempCapitals = new ArrayList<Integer>();
        for (int i3 = 1; i3 < this.getCivsSize(); ++i3) {
            tempOwners.add(new ArrayList());
            for (int j = 0; j < this.getCiv(i3).getNumOfProvs(); ++j) {
                ((List)tempOwners.get(i3 - 1)).add(this.getCiv(i3).getProvID(j));
            }
            tempCapitals.add(this.getCiv(i3).getCapitalProvID());
        }
        int provincePop = 0;
        for (i = 1; i < this.getCivsSize(); ++i) {
            for (int j = 0; j < ((List)tempOwners.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1)).size(); ++j) {
                this.getProv((Integer)((List)tempOwners.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1)).get(j)).setCivId(i, false);
                this.getProv((Integer)((List)tempOwners.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1)).get(j)).setTrueOwnerOfProv(i);
                this.getProv((Integer)((List)tempOwners.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1)).get(j)).getCores().addNewCore(i, 1);
                provincePop = (int)this.getProv((Integer)((List)tempOwners.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1)).get(j)).getPop().getPops();
                this.getProv((Integer)((List)tempOwners.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1)).get(j)).getPop().clearData();
                this.getProv((Integer)((List)tempOwners.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1)).get(j)).getPop().setPopulationOfCivID(i, provincePop);
            }
        }
        for (i = 1; i < this.getCivsSize(); ++i) {
            this.getCiv(i).setCapitalProvID((Integer)tempCapitals.get((Integer)lTakeProvinceOfCivID.get(i - 1) - 1));
            if (this.getCiv(i).getPuppetOfCiv() == i) continue;
            this.getCiv(i).setPuppetOfCivId(i);
        }
        tempOwners.clear();
        tempOwners = null;
        i = 1;
        while (i < this.getPlayersSize()) {
            this.removePlayer(i);
        }
        if (this.getPlayer(0).getCivId() < 0) {
            this.setActiveProvID(this.getActiveProvID());
        } else {
            this.setActiveProvID(this.getCiv(this.getPlayer(0).getCivId()).getCapitalProvID());
        }
        CFG.core.buildCivilizationsRegions();
        CFG.core.enableDrawCivlizationsRegions_Players();
        CFG.map.getMpC().centerToProvID(this.getActiveProvID());
        CFG.setActiveCivInfoId(this.getProv(this.getActiveProvID()).getCivId());
        CFG.updateActiveCivInfo_CreateNewGame();
    }

