                    if (!this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getProvBordersLandByLand(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getIsCivilizationBorder()) continue;
