    public final void disableDrawCivilizationRegions(int nCivID) {
        if (nCivID <= 0) {
            return;
        }
        try {
            this.removeActiveCivRegion_CivID(nCivID);
            for (int i = 0; i < this.getCiv(nCivID).getCivRegionsSize(); ++i) {
                for (int j = 0; j < this.getCiv(nCivID).getCivRegion(i).getProvincesSize(); ++j) {
                    for (int k = 0; k < this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvincesSize(); ++k) {
                        if (this.getCiv(nCivID).getCivRegion(i).getProvince(j) < this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)) {
                            if (!this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getProvBordersLandByLand(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getIsCivilizationBorder()) continue;
                            if (!this.isActiveCivRegion_CivID(this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivId(), this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivRegionID())) {
                                this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getProvBordersLandByLand(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).updateDrawProvinceBorder(this.getCiv(nCivID).getCivRegion(i).getProvince(j));
                                continue;
                            }
                            this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivId())).getRegionStyleID(this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivRegionID())).updatePB(this.getCiv(nCivID).getCivRegion(i).getProvince(j), this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k));
                            continue;
                        }
                        if (!this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getProvBordersLandByLand(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getIsCivilizationBorder()) continue;
                        if (!this.isActiveCivRegion_CivID(this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivId(), this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivRegionID())) {
                            this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getProvBordersLandByLand(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).updateDrawProvinceBorder(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k));
                            continue;
                        }
                        this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivId())).getRegionStyleID(this.getProv(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k)).getCivRegionID())).updatePB(this.getProv(this.getCiv(nCivID).getCivRegion(i).getProvince(j)).getNeighProvinces(k), this.getCiv(nCivID).getCivRegion(i).getProvince(j));
                    }
                }
            }
        }
        catch (Exception exception) {
            
        }
    }

    private final void addActiveCivRegion_CivID(int nCivID, int nCivRegionStyle) {
        int i;
        for (i = this.lActive_CivRegion.size() - 1; i >= 0; --i) {
            if (nCivID != this.lActive_CivRegion.get(i).getCivID()) continue;
            if (this.lActive_CivRegion.get(i).getActiveRegionsSize() != this.getCiv(nCivID).getCivRegionsSize()) {
                this.lActive_CivRegion.remove(i);
                break;
            }
            return;
        }
        for (i = 0; i < this.getCiv(nCivID).getCivRegionsSize(); ++i) {
            this.addActiveCivRegion_RegionID(nCivID, i, nCivRegionStyle);
        }
    }

    private final void addActiveCivRegion_RegionID(int nCivID, int nRegionID, int nCivRegionStyle) {
        for (int i = this.lActive_CivRegion.size() - 1; i >= 0; --i) {
            if (nCivID != this.lActive_CivRegion.get(i).getCivID()) continue;
            if (this.lActive_CivRegion.get(i).isActive_RegionID(nRegionID)) {
                return;
            }
            this.lActive_CivRegion.get(i).addRegion(nRegionID, nCivRegionStyle);
            return;
        }
        this.lActive_CivRegion.add(new Civilization_Region_Active(nCivID, nRegionID, nCivRegionStyle));
    }

    private final void removeActiveCivRegion_CivID(int nCivID) {
        for (int i = this.lActive_CivRegion.size() - 1; i >= 0; --i) {
            if (nCivID != this.lActive_CivRegion.get(i).getCivID()) continue;
            this.lActive_CivRegion.remove(i);
            return;
        }
    }

    private final void removeActiveCivRegion_RegionID(int nCivID, int nRegionID) {
        for (int i = this.lActive_CivRegion.size() - 1; i >= 0; --i) {
            if (nCivID != this.lActive_CivRegion.get(i).getCivID()) continue;
            if (this.lActive_CivRegion.get(i).getActiveRegionsSize() == 1) {
                this.lActive_CivRegion.remove(i);
            }
            this.lActive_CivRegion.get(i).removeRegion(nRegionID);
            return;
        }
    }

