    public final boolean createScenarioAddCivilization(String nCivTag, int nProvinceID, boolean rebuildCores, boolean addCore, boolean isInGame, boolean loadFlag) {
        if (!nCivTag.equals("ran")) {
            for (int i = 0; i < this.getCivsSize(); ++i) {
                if (!this.getCiv(i).getCivTag().equals(nCivTag)) continue;
                if (this.getCiv(i).getCapitalProvID() >= 0) {
                    this.getProv(this.getCiv(i).getCapitalProvID()).setIsCapital(false);
                }
                this.getCiv(i).setCapitalProvID(nProvinceID);
                if (this.getCiv(i).getCapitalProvID() >= 0) {
                    this.getProv(this.getCiv(i).getCapitalProvID()).setIsCapital(true);
                }
                return false;
            }
        }
        try {
            int i;
            Civilization_GameData3 civData = Core.loadCivilization(nCivTag);
            this.lCivs.add(new Civilization(nCivTag, civData.getR(), civData.getG(), civData.getB(), nProvinceID, this.iCivsSize, civData.iReligionID, civData.iGroupID, loadFlag));
            this.iCivsSize = this.lCivs.size();
            this.getCiv(this.iCivsSize - 1).setCivId(this.iCivsSize - 1);
            this.getCiv(this.iCivsSize - 1).civGD.sCivDescription = civData.getDescription();
            if (this.getCiv(this.iCivsSize - 1).getCapitalProvID() >= 0) {
                this.getProv(this.getCiv(this.iCivsSize - 1).getCapitalProvID()).setTrueOwnerOfProv(this.iCivsSize - 1);
                this.getProv(this.getCiv(this.iCivsSize - 1).getCapitalProvID()).setCivId(this.iCivsSize - 1, false, isInGame);
                this.getProv(this.getCiv(this.iCivsSize - 1).getCapitalProvID()).updateArmy4(this.getGameScenars().getScenario_StartingArmyInCapitals());
            }
            if (!loadFlag) {
                Core.addSimpleTask(new SimpleTask("loadFlag" + (this.iCivsSize - 1), this.iCivsSize - 1){

                    @Override
                    public void update() {
                        CFG.core.getCiv(this.id).loadFlag();
                    }
                });
            }
            this.getCiv(this.iCivsSize - 1).setGold(-999999L);
            CFG.addCreateScenario_TechnologyLevelsByContinents_Civ();
            CFG.core.getCiv(this.getCivsSize() - 1).buildDiplomacy(true);
            for (i = 0; i < this.getCivsSize(); ++i) {
                CFG.core.getCiv(i).updateDiplomacy_AfterAddingCivilization();
            }
            if (CFG.palletManager.getActivePalletID() > 0) {
                CFG.palletManager.loadCivilizationPalletColor(CFG.palletManager.getActivePalletID(), this.getCivsSize() - 1);
            }
            for (i = 0; i < CFG.core.getPlayersSize(); ++i) {
                CFG.core.getPlayer(i).addMetCiv(false);
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
        if (nProvinceID >= 0) {
            if (rebuildCores) {
                this.getProv(nProvinceID).buildProvinceCore();
                CFG.province_CoresGD.clearCoresData(nProvinceID);
            } else if (addCore) {
                this.getProv(nProvinceID).getCores().addNewCore(this.iCivsSize - 1, GameCalendar.TURNID);
            }
        }
        return true;
    }

    
