    public final void checkArmies() {
        for (int i = 0; i < this.getProvinSize(); ++i) {
            if (this.getProv(i).getWastelandLvl() >= 0 || this.getProv(i).getSeaProv()) continue;
            if (this.getProv(i).getCivId() == 0) {
                if (this.getProv(i).getCivsSize() <= 1) continue;
                try {
                    while (this.getProv(i).getCivsSize() > 1) {
                        this.getProv(i).updateArmy4(this.getProv(i).getCivId(1), 0);
                    }
                    continue;
                }
                catch (StackOverflowError e) {
                    if (!CFG.LOGs) continue;
                    CFG.exceptionStack(e);
                    continue;
                }
                catch (Exception ex) {
                    if (!CFG.LOGs) continue;
                    CFG.exceptionStack(ex);
                    continue;
                }
            }
            for (int j = 1; j < this.getProv(i).getCivsSize(); ++j) {
                if (!this.getProvSelected().canAddArmy(this.getProv(i).getCivId(j), i)) {
                    this.getProv(i).updateArmy4(this.getProv(i).getCivId(j), 0);
                    --j;
                    continue;
                }
                if (this.getProv(i).getCivId(j) != this.getProv(i).getCivId()) continue;
                this.getProv(i).updateArmy4(this.getProv(i).getArmyID(j));
                this.getProv(i).removeArmy_ID(j);
                --j;
            }
        }
    }

