    public int armyExperienceRequired(int civID) {
        return 100 * (int)Math.pow(2.0, (double)CFG.core.getCiv((int)civID).civGD.armyExpertiseLevel);
    }

    public void addArmyExperience(int civID, float exp) {
        if (CFG.core.getCiv((int)civID).civGD.armyExpertiseLevel < GameValues.gvMilitary.MILITARY_EXPERTISE_MAX_LEVEL && exp > 0.0f) {
            CFG.core.getCiv((int)civID).civGD.armyExperience += exp;
            if (CFG.core.getCiv((int)civID).civGD.armyExperience >= (float)this.armyExperienceRequired(civID)) {
                CFG.core.getCiv((int)civID).civGD.armyExperience = Math.max(0.0f, CFG.core.getCiv((int)civID).civGD.armyExperience - (float)this.armyExperienceRequired(civID));
                ++CFG.core.getCiv((int)civID).civGD.armyExpertiseLevel;
                if (CFG.core.getCiv(civID).getIsPlayer()) {
                    CFG.core.getCiv((int)civID).getCivDiploGD().messageBox.addMessage(new Message_MilitaryExpPoints(civID));
                } else if (CFG.oR.nextInt(100) < GameValues.gvMilitary.AI_MILITARY_EXPERTISE_ATTACK_CHANCE_100) {
                    if (!this.addArmyExpertiseAttack(civID)) {
                        this.addArmyExpertiseDefense(civID);
                    }
                } else if (!this.addArmyExpertiseDefense(civID)) {
                    this.addArmyExpertiseAttack(civID);
                }
            }
        }
    }

    public int armyExpertisePointsLeft(int civID) {
        return CFG.core.getCiv((int)civID).civGD.armyExpertiseLevel - CFG.core.getCiv((int)civID).civGD.armyExpertiseAttack - CFG.core.getCiv((int)civID).civGD.armyExpertiseDefense;
    }

    public boolean addArmyExpertiseAttack(int civID) {
        if (CFG.core.armyExpertisePointsLeft(civID) <= 0) {
            return false;
        }
        if (CFG.core.getCiv((int)civID).civGD.armyExpertiseAttack < GameValues.gvMilitary.MILITARY_EXPERTISE_MAX_ATTACK) {
            ++CFG.core.getCiv((int)civID).civGD.armyExpertiseAttack;
            return true;
        }
        return false;
    }

    public boolean addArmyExpertiseDefense(int civID) {
        if (CFG.core.armyExpertisePointsLeft(civID) <= 0) {
            return false;
        }
        if (CFG.core.getCiv((int)civID).civGD.armyExpertiseDefense < GameValues.gvMilitary.MILITARY_EXPERTISE_MAX_DEFENSE) {
            ++CFG.core.getCiv((int)civID).civGD.armyExpertiseDefense;
            return true;
        }
        return false;
    }

