    public final void addPlayer(int nCivID) {
        this.lPlayers.add(new Player(nCivID));
        this.iPlayersSize = this.lPlayers.size();
    }

    public final void addPlayer2(int stack) {
        if (this.getPlayersSize() >= this.getGameScenars().getScenarioNumOfCivs(this.getScenarioID())) {
            return;
        }
        if (stack > 59) {
            this.lPlayers.add(new Player(1));
            this.iPlayersSize = this.lPlayers.size();
            return;
        }
        int tempResult = CFG.oR.nextInt(this.gameScenarios.getScenarioNumOfCivs(this.scenarioID)) + 1;
        try {
            if (this.getCiv(tempResult).getNumOfProvs() == 0) {
                this.addPlayer2(++stack);
                return;
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
        for (int i = 0; i < this.iPlayersSize; ++i) {
            if (this.getPlayer(i).getCivId() != tempResult) continue;
            this.addPlayer2(++stack);
            return;
        }
        this.lPlayers.add(new Player(tempResult));
        this.iPlayersSize = this.lPlayers.size();
        CFG.menus.rebuildCivs_Info_Players();
    }

    public final void removePlayer(int i) {
        try {
            if (i == 0 && this.getPlayersSize() == 1) {
                return;
            }
            this.getPlayer(i).disposePlayersFlag();
            if (this.lPlayers.get(i).getCivId() > 0) {
                CFG.core.getCiv(this.lPlayers.get(i).getCivId()).setIsPlayer(false);
            }
            this.lPlayers.remove(i);
            this.iPlayersSize = this.lPlayers.size();
            if (CFG.menus.getInCreateNewGame()) {
                CFG.menus.rebuildCivs_Info_Players();
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

