    public final void updateProvincesInView() {
        if (!this.uPRV && Math.abs(this.lastPosX - CFG.map.getMpC().getPX()) < 2.0f && Math.abs(this.lastPosY - CFG.map.getMpC().getPY()) < 2.0f && Math.abs(this.lastScale - CFG.map.getMpS().getCurrSc()) < 0.001f) {
            return;
        }
        this.lastPosX = CFG.map.getMpC().getPX();
        this.lastPosY = CFG.map.getMpC().getPY();
        this.lastScale = CFG.map.getMpS().getCurrSc();
        
        int i;
        this.uPRV = false;
        for (i = 0; i < CFG.NUM_OF_PROVINCES_IN_VIEW; ++i) {
            this.getProv(this.getPIV(i)).setDrawProv(false);
        }
        for (i = 0; i < CFG.NUM_OF_SEA_PROVINCES_IN_VIEW; ++i) {
            this.getProv(this.getPSVI(i)).setDrawProv(false);
        }
        for (i = 0; i < CFG.NUM_OF_WASTELAND_PROVINCES_IN_VIEW; ++i) {
            this.getProv(this.getWPIV(i)).setDrawProv(false);
        }
        CFG.NUM_OF_PROVINCES_IN_VIEW = 0;
        CFG.NUM_OF_SEA_PROVINCES_IN_VIEW = 0;
        CFG.NUM_OF_WASTELAND_PROVINCES_IN_VIEW = 0;
        this.prIV.clear();
        this.pSIV.clear();
        this.wPIV.clear();
        for (i = 0; i < this.iRegionsSize; ++i) {
            if (!this.inViewY(this.lRegions.get(i).getMinY(), this.lRegions.get(i).getMaxY())) continue;
            if (this.inViewX(this.lRegions.get(i).getMinX(), this.lRegions.get(i).getMaxX()) || this.inViewX2(this.lRegions.get(i).getMinX(), this.lRegions.get(i).getMaxX())) {
                this.updateDrawRegionProvinces(i);
                continue;
            }
            if (!this.lRegions.get(i).getBelowZero() || !this.inViewXBelowZero(this.lRegions.get(i).getMinX(), this.lRegions.get(i).getMaxX())) continue;
            this.updateDrawRegionProvinces(i);
        }
        CFG.NUM_OF_PROVINCES_IN_VIEW = this.prIV.size();
        CFG.NUM_OF_SEA_PROVINCES_IN_VIEW = this.pSIV.size();
        CFG.NUM_OF_WASTELAND_PROVINCES_IN_VIEW = this.wPIV.size();
        
        if (this.updateSortedPIV || CFG.NUM_OF_PROVINCES_IN_VIEW != this.sortedPIV.size()) {
            this.sortedPIV.clear();
            this.sortedPIV.addAll(this.prIV);
            this.sortedPIV.sort((a, b) -> {
                Province pA = this.getProv(a);
                Province pB = this.getProv(b);
                
                com.badlogic.gdx.graphics.g2d.TextureRegion regA = ProvinceAtlas.getRegion(a);
                com.badlogic.gdx.graphics.g2d.TextureRegion regB = ProvinceAtlas.getRegion(b);
                
                if (regA != null && regB != null) {
                    int texCompare = Integer.compare(regA.getTexture().hashCode(), regB.getTexture().hashCode());
                    if (texCompare != 0) return texCompare;
                }

                int civCompare = Integer.compare(pA.getCivId(), pB.getCivId());
                if (civCompare != 0) return civCompare;
                
                int metCompare = Boolean.compare(CFG.getMetProv(a), CFG.getMetProv(b));
                if (metCompare != 0) return metCompare;
                
                return Integer.compare(a, b);
            });
            this.updateSortedPIV = false;
        }
    }

