    private final void updateDrawRegionProvinces(int iID) {
        if (this.inViewY_WholeRegion(this.lRegions.get(iID).getMinY(), this.lRegions.get(iID).getMaxY())) {
            if (this.inViewX_WholeRegion(this.lRegions.get(iID).getMinX(), this.lRegions.get(iID).getMaxX())) {
                for (int i = 0; i < this.lRegions.get(iID).getProvincesSize(); ++i) {
                    this.getProv(this.lRegions.get(iID).getProvince(i)).setTranslateProvPosX(CFG.map.getMpC().getSecondSideOfMap_MoveX() + CFG.map.getMpC().getPX());
                    this.getProv(this.lRegions.get(iID).getProvince(i)).setDrawProv(true);
                    if (this.getProv(this.lRegions.get(iID).getProvince(i)).getWastelandLvl() >= 0) {
                        this.wPIV.add(this.lRegions.get(iID).getProvince(i));
                        continue;
                    }
                    if (this.getProv(this.lRegions.get(iID).getProvince(i)).getSeaProv()) {
                        this.pSIV.add(this.lRegions.get(iID).getProvince(i));
                        continue;
                    }
                    this.prIV.add(this.lRegions.get(iID).getProvince(i));
                }
                return;
            }
            if (this.inViewX_WholeRegion2(this.lRegions.get(iID).getMinX(), this.lRegions.get(iID).getMaxX())) {
                for (int i = 0; i < this.lRegions.get(iID).getProvincesSize(); ++i) {
                    this.getProv(this.lRegions.get(iID).getProvince(i)).setTranslateProvPosX(CFG.map.getMpC().getPX());
                    this.getProv(this.lRegions.get(iID).getProvince(i)).setDrawProv(true);
                    if (this.getProv(this.lRegions.get(iID).getProvince(i)).getWastelandLvl() >= 0) {
                        this.wPIV.add(this.lRegions.get(iID).getProvince(i));
                        continue;
                    }
                    if (this.getProv(this.lRegions.get(iID).getProvince(i)).getSeaProv()) {
                        this.pSIV.add(this.lRegions.get(iID).getProvince(i));
                        continue;
                    }
                    this.prIV.add(this.lRegions.get(iID).getProvince(i));
                }
                return;
            }
        }
        for (int i = 0; i < this.lRegions.get(iID).getProvincesSize(); ++i) {
            this.updateDrawProvince(this.lRegions.get(iID).getProvince(i));
        }
    }

    public final void updateDrawProvince(int nProvinceID) {
        if (this.inViewY(nProvinceID)) {
            if (this.inViewX(nProvinceID)) {
                this.getProv(nProvinceID).setTranslateProvPosX(CFG.map.getMpC().getSecondSideOfMap_MoveX() + CFG.map.getMpC().getPX());
                this.getProv(nProvinceID).setDrawProv(true);
                if (this.getProv(nProvinceID).getWastelandLvl() >= 0) {
                    this.wPIV.add(nProvinceID);
                } else if (this.getProv(nProvinceID).getSeaProv()) {
                    this.pSIV.add(nProvinceID);
                } else {
                    this.prIV.add(nProvinceID);
                }
            } else if (this.inViewX2(nProvinceID)) {
                this.getProv(nProvinceID).setTranslateProvPosX(CFG.map.getMpC().getPX());
                this.getProv(nProvinceID).setDrawProv(true);
                if (this.getProv(nProvinceID).getWastelandLvl() >= 0) {
                    this.wPIV.add(nProvinceID);
                } else if (this.getProv(nProvinceID).getSeaProv()) {
                    this.pSIV.add(nProvinceID);
                } else {
                    this.prIV.add(nProvinceID);
                }
            } else if (this.getProv(nProvinceID).getIsBelowZero()) {
                if (this.inViewXBelowZero(nProvinceID)) {
                    this.getProv(nProvinceID).setTranslateProvPosX(CFG.map.getMpB().getWidthM() + CFG.map.getMpC().getPX());
                    this.getProv(nProvinceID).setDrawProv(true);
                    if (this.getProv(nProvinceID).getWastelandLvl() >= 0) {
                        this.wPIV.add(nProvinceID);
                    } else if (this.getProv(nProvinceID).getSeaProv()) {
                        this.pSIV.add(nProvinceID);
                    } else {
                        this.prIV.add(nProvinceID);
                    }
                } else {
                    this.getProv(nProvinceID).setTranslateProvPosX(CFG.map.getMpC().getPX());
                    this.getProv(nProvinceID).setDrawProv(false);
                }
            } else {
                this.getProv(nProvinceID).setTranslateProvPosX(CFG.map.getMpC().getPX());
                this.getProv(nProvinceID).setDrawProv(false);
            }
        } else {
            this.getProv(nProvinceID).setTranslateProvPosX(CFG.map.getMpC().getPX());
            this.getProv(nProvinceID).setDrawProv(false);
        }
    }

    public final void drawActiveProvince(SpriteBatch oSB) {
        block11: {
            if (this.iActiveProv >= 0 && this.getProv(this.iActiveProv).getDrawProv()) {
                if (CFG.chooseProvinceMode) {
                    oSB.setColor(new Color(CFG.getColorStep(255, 55, this.activeProvAnimationData.getColorStepID(), 30), CFG.getColorStep(255, 55, this.activeProvAnimationData.getColorStepID(), 30), CFG.getColorStep(255, 55, this.activeProvAnimationData.getColorStepID(), 30), this.getProv(this.iActiveProv).getSeaProv() ? (float)(this.activeProvAnimationData.getAlpha() + 35) / 255.0f / 3.0f : (float)(this.activeProvAnimationData.getAlpha() + 35) / 255.0f * (this.fDashedLine_Percentage_HighlitedProvinceBorder / 100.0f)));
                    this.getProv(this.iActiveProv).drawProv_ActiveProv(oSB);
                } else {
                    if (this.getProv(this.iActiveProv).getSeaProv()) {
                        oSB.setColor(new Color(1.0f, 1.0f, 1.0f, (float)this.activeProvAnimationData.getAlpha() / 2.0f / 255.0f));
                    } else {
                        oSB.setColor(new Color(1.0f, 1.0f, 1.0f, (float)this.activeProvAnimationData.getAlpha() / 255.0f));
                    }
                    this.getProv(this.iActiveProv).drawProv_ActiveProv(oSB);
                }
            }
            try {
                if (MenuManager.iHoveredProvinceID >= 0 && this.iActiveProv != MenuManager.iHoveredProvinceID && this.getProv(MenuManager.iHoveredProvinceID).getDrawProv()) {
                    oSB.setColor(new Color(1.0f, 1.0f, 1.0f, this.getProv(MenuManager.iHoveredProvinceID).getSeaProv() ? 0.02f : 0.05f));
                    this.getProv(MenuManager.iHoveredProvinceID).drawProv_ActiveProv(oSB);
                }
            }
            catch (Exception ex) {
                if (!CFG.LOGs) break block11;
                CFG.exceptionStack(ex);
            }
        }
        try {
            for (int i = 0; i < CFG.chosenProvinces_Regroup.size(); ++i) {
                oSB.setColor(new Color(Colors.COLOR_INGAME_GOLD.r, Colors.COLOR_INGAME_GOLD.g, Colors.COLOR_INGAME_GOLD.b, (float)(this.activeProvAnimationData2.getAlpha() + 35) / 255.0f));
                this.getProv(CFG.chosenProvinces_Regroup.get(i)).drawProv_ActiveProv(oSB);
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

