    public final Point_XY2 updateSeaProvince_CenterArmyPostion(int i, float nScale) {
        Point_XY2 tempBegin = null;
        Point_XY2 tempEnd = null;
        for (int j = this.getProv(i).getProvinceArmyBoxes().size() - 1; j >= 0; --j) {
            if (-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight() > this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosY() || !((float)(-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight()) + (float)(CFG.GAMEHEIGHT - IMGManager.getIMG(Images.topFlagBG).getHeight() - CFG.BUTTON_H - CFG.PADD * 2) / CFG.map.getMpS().getCurrSc() >= (float)this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosY())) continue;
            if ((float)(-CFG.map.getMpC().getPX()) + (float)CFG.GAMEWIDTH / CFG.map.getMpS().getCurrSc() >= (float)this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosX() && -CFG.map.getMpC().getPX() <= this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosX()) {
                tempBegin = new Point_XY2(this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosX(), this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosY());
                tempEnd = new Point_XY2(this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosX(), this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosY());
                if (this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosX() < -CFG.map.getMpC().getPX()) {
                    tempBegin.setPX(-CFG.map.getMpC().getPX());
                }
                if (this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosY() < -CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight()) {
                    tempBegin.setPY(-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight());
                }
                if ((float)this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosX() > (float)(-CFG.map.getMpC().getPX()) + (float)CFG.GAMEWIDTH / CFG.map.getMpS().getCurrSc()) {
                    tempEnd.setPX((int)((float)(-CFG.map.getMpC().getPX()) + (float)CFG.GAMEWIDTH / CFG.map.getMpS().getCurrSc()));
                }
                if ((float)this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosY() > (float)(-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight()) + (float)(CFG.GAMEHEIGHT - IMGManager.getIMG(Images.topFlagBG).getHeight() - CFG.BUTTON_H - CFG.PADD * 2) / CFG.map.getMpS().getCurrSc()) {
                    tempEnd.setPY((int)((float)(-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight()) + (float)(CFG.GAMEHEIGHT - IMGManager.getIMG(Images.topFlagBG).getHeight() - CFG.BUTTON_H - CFG.PADD * 2) / CFG.map.getMpS().getCurrSc()));
                }
                return new Point_XY2((int)(((float)(tempBegin.getPX() + tempEnd.getPX()) / 2.0f + (float)this.getProv(i).getTranslateProvPosX()) * nScale), (int)(((float)(tempBegin.getPY() + tempEnd.getPY()) / 2.0f + (float)CFG.map.getMpC().getPY()) * nScale));
            }
            if (!((float)(-CFG.map.getMpC().getPX()) + (float)CFG.GAMEWIDTH / CFG.map.getMpS().getCurrSc() >= (float)(this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosX() + CFG.map.getMpB().getWidthM())) || -CFG.map.getMpC().getPX() > this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosX() + CFG.map.getMpB().getWidthM()) continue;
            tempBegin = new Point_XY2(this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosX() + CFG.map.getMpB().getWidthM(), this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosY());
            tempEnd = new Point_XY2(this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosX() + CFG.map.getMpB().getWidthM(), this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosY());
            if (this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosX() + CFG.map.getMpB().getWidthM() < -CFG.map.getMpC().getPX()) {
                tempBegin.setPX(-CFG.map.getMpC().getPX());
            }
            if (this.getProv(i).getProvinceArmyBoxes().get(j).getStartPosY() < -CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight()) {
                tempBegin.setPY(-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight());
            }
            if ((float)(this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosX() + CFG.map.getMpB().getWidthM()) > (float)(-CFG.map.getMpC().getPX()) + (float)CFG.GAMEWIDTH / CFG.map.getMpS().getCurrSc()) {
                tempEnd.setPX((int)((float)(-CFG.map.getMpC().getPX()) + (float)CFG.GAMEWIDTH / CFG.map.getMpS().getCurrSc()));
            }
            if ((float)this.getProv(i).getProvinceArmyBoxes().get(j).getEndPosY() > (float)(-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight()) + (float)(CFG.GAMEHEIGHT - IMGManager.getIMG(Images.topFlagBG).getHeight() - CFG.BUTTON_H - CFG.PADD * 2) / CFG.map.getMpS().getCurrSc()) {
                tempEnd.setPY((int)((float)(-CFG.map.getMpC().getPY() + IMGManager.getIMG(Images.topFlagBG).getHeight()) + (float)(CFG.GAMEHEIGHT - IMGManager.getIMG(Images.topFlagBG).getHeight() - CFG.BUTTON_H - CFG.PADD * 2) / CFG.map.getMpS().getCurrSc()));
            }
            return new Point_XY2((int)(((float)(tempBegin.getPX() + tempEnd.getPX()) / 2.0f + (float)CFG.map.getMpC().getPX()) * nScale), (int)(((float)(tempBegin.getPY() + tempEnd.getPY()) / 2.0f + (float)CFG.map.getMpC().getPY()) * nScale));
        }
        return new Point_XY2((int)((float)(this.getProv(i).getCeX() + this.getProv(i).getShPX() + this.getProv(i).getTranslateProvPosX()) * nScale), (int)((float)(this.getProv(i).getCeY() + this.getProv(i).getShPY() + CFG.map.getMpC().getPY()) * nScale));
    }

