    private final int getDisplayedArmyCivID(int nProvinceID, int armyID) {
        int armyCivID = this.getProv(nProvinceID).getCivId(armyID);
        int playerCivID = CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId();
        if (CFG.gameAction.isArmyControlledByCivInProvince(nProvinceID, armyCivID, playerCivID)) {
            return playerCivID;
        }
        return armyCivID;
    }

