        IMGManager.getIMG(Images.army_capital_frame).draw2(oSB, tCenterX + (int)Math.ceil((float)tFlagWidth / 2.0f) - IMGManager.getIMG(Images.army_capital_frame).getWidth(), tCenterY + CFG.ARMY_HEIGHT + CFG.ARMY_BG_EXTRA_HEIGHT * 2 - IMGManager.getIMG(Images.army_capital_frame).getHeight(), IMGManager.getIMG(Images.army_capital_frame).getWidth(), IMGManager.getIMG(Images.army_capital_frame).getHeight(), true, true);
