        this.getCiv(nCivID).getFlagC().drawO(oSB, tCenterX - tFlagWidth / 2, tCenterY - this.getCiv(nCivID).getFlagC().getHeight(), tFlagWidth, CFG.ARMY_HEIGHT + CFG.ARMY_BG_EXTRA_HEIGHT * 2);
