    public final int getDrawProvinceArmy_EndPosY(int nProvinceID, float nScale) {
        int nArmies = 0;
        for (int i = 0; i < this.getProv(nProvinceID).getCivsSize(); ++i) {
            if (this.getProv(nProvinceID).getArmyID(i) <= 0 && !this.getProv(nProvinceID).isCapital()) continue;
            ++nArmies;
        }
        return (int)((float)(this.getProv(nProvinceID).getCeY() + this.getProv(nProvinceID).getShPY() + CFG.map.getMpC().getPY()) * nScale) - Core.getArmyHeight() / 2 + (CFG.ARMY_BG_EXTRA_HEIGHT + Core.getArmyHeight()) * nArmies - (this.getProv(nProvinceID).getCivsSize() > 1 ? Core.getArmyHeight() * (this.getProv(nProvinceID).getCivsSize() - 1) / 2 : 0);
    }

