    public final void drawProvinceBuildings(SpriteBatch oSB, int tCenterX, int tCenterY, int nProvinceID) {
        lBuildingsImages.clear();
        if (CFG.core.getProv(nProvinceID).getLvlOfFort() > 0) {
            lBuildingsImages.add(Images.bFort);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfWatchTower() > 0) {
            lBuildingsImages.add(Images.bTower);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfPort() > 0) {
            lBuildingsImages.add(Images.bPort);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfLibrary() > 0) {
            lBuildingsImages.add(Images.bLibrary);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfFarm() > 0) {
            lBuildingsImages.add(Images.bFarm);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfWorkshop() > 0) {
            lBuildingsImages.add(Images.bWorkshop);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfMarket() > 0) {
            lBuildingsImages.add(Images.bMarket);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfArmoury() > 0) {
            lBuildingsImages.add(Images.bArmoury);
        }
        if (CFG.core.getProv(nProvinceID).getLvlOfSupply() > 0) {
            lBuildingsImages.add(Images.bSupply);
        }
        if (lBuildingsImages.size() > 0) {
            int i;
            int tFlagWidth = (int)((float)CFG.ARMY_HEIGHT * 100.0f / (float)CFG.CIV_FLAG_HEIGHT * (float)CFG.CIV_FLAG_WIDTH / 100.0f);
            iBuildingsWidth = 0;
            for (i = lBuildingsImages.size() - 1; i >= 0; --i) {
                iBuildingsWidth += (int)((float)(IMGManager.getIMG(lBuildingsImages.get(i)).getWidth() * CFG.ARMY_HEIGHT) * 100.0f / (float)IMGManager.getIMG(lBuildingsImages.get(i)).getHeight() / 100.0f) + CFG.PADD;
            }
            oSB.setColor(new Color(CFG.COLOR_GRADIENT_DARK_BLUE.r, CFG.COLOR_GRADIENT_DARK_BLUE.g, CFG.COLOR_GRADIENT_DARK_BLUE.b, 0.8f));
            IMGManager.getIMG(Images.line32Off1).drawO(oSB, tCenterX - ((iBuildingsWidth -= CFG.PADD) + CFG.ARMY_BG_EXTRA_WIDTH * 2) / 2 - tFlagWidth - CFG.ARMY_BG_EXTRA_WIDTH - CFG.PADD * 2, tCenterY - CFG.ARMY_HEIGHT / 2 - CFG.ARMY_BG_EXTRA_HEIGHT - IMGManager.getIMG(Images.line32Off1).getHeight() - 1, iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2 + tFlagWidth + CFG.ARMY_BG_EXTRA_WIDTH + CFG.PADD * 4, CFG.ARMY_HEIGHT + CFG.ARMY_BG_EXTRA_HEIGHT * 2 + 2);
            oSB.setColor(new Color(1.0f, 1.0f, 1.0f, 0.1f));
            IMGManager.getIMG(Images.line32Off1).drawO(oSB, tCenterX - (iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2) / 2 - tFlagWidth - CFG.ARMY_BG_EXTRA_WIDTH - CFG.PADD * 2, tCenterY - CFG.ARMY_HEIGHT / 2 - CFG.ARMY_BG_EXTRA_HEIGHT - IMGManager.getIMG(Images.line32Off1).getHeight(), iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2 + tFlagWidth + CFG.ARMY_BG_EXTRA_WIDTH + CFG.PADD * 4, 1);
            IMGManager.getIMG(Images.line32Off1).drawO(oSB, tCenterX - (iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2) / 2 - tFlagWidth - CFG.ARMY_BG_EXTRA_WIDTH - CFG.PADD * 2, tCenterY - CFG.ARMY_HEIGHT / 2 - CFG.ARMY_BG_EXTRA_HEIGHT - IMGManager.getIMG(Images.line32Off1).getHeight() + CFG.ARMY_HEIGHT + CFG.ARMY_BG_EXTRA_HEIGHT * 2 - 1, iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2 + tFlagWidth + CFG.ARMY_BG_EXTRA_WIDTH + CFG.PADD * 4, 1);
            oSB.setColor(Color.WHITE);
            int tX = CFG.ARMY_BG_EXTRA_WIDTH;
            for (i = lBuildingsImages.size() - 1; i >= 0; --i) {
                IMGManager.getIMG(lBuildingsImages.get(i)).drawO(oSB, tCenterX - (iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2) / 2 + tX, tCenterY - CFG.ARMY_HEIGHT / 2 - IMGManager.getIMG(lBuildingsImages.get(i)).getHeight(), (int)((float)(IMGManager.getIMG(lBuildingsImages.get(i)).getWidth() * CFG.ARMY_HEIGHT) * 100.0f / (float)IMGManager.getIMG(lBuildingsImages.get(i)).getHeight() / 100.0f), CFG.ARMY_HEIGHT);
                tX += (int)((float)(IMGManager.getIMG(lBuildingsImages.get(i)).getWidth() * CFG.ARMY_HEIGHT) * 100.0f / (float)IMGManager.getIMG(lBuildingsImages.get(i)).getHeight() / 100.0f) + CFG.PADD;
            }
            this.getCiv(CFG.core.getProv(nProvinceID).getCivId()).getFlagC().drawO(oSB, tCenterX - (iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2) / 2 - tFlagWidth, tCenterY - CFG.ARMY_HEIGHT / 2 - this.getCiv(CFG.core.getProv(nProvinceID).getCivId()).getFlagC().getHeight(), tFlagWidth, CFG.ARMY_HEIGHT);
            IMGManager.getIMG(Images.flagRectSmall).drawO(oSB, tCenterX - (iBuildingsWidth + CFG.ARMY_BG_EXTRA_WIDTH * 2) / 2 - tFlagWidth, tCenterY - CFG.ARMY_HEIGHT / 2 - IMGManager.getIMG(Images.flagRectSmall).getHeight(), tFlagWidth, CFG.ARMY_HEIGHT);
        }
    }

