    public final void drawAllProvinces_Name_Flag(SpriteBatch oSB, float nScale) {
        for (int i = 0; i < CFG.NUM_OF_PROVINCES_IN_VIEW; ++i) {
            if (this.getProv(this.getPIV(i)).getCivId() == 0 || this.getProv(this.getPIV(i)).isCapital()) continue;
            this.drawCivilization_Flag(oSB, this.getPIV(i), nScale);
        }
        this.drawAllCivilizations_Name_Flag_InCapitals(oSB, nScale);
    }

    public final void drawCores_Flags(SpriteBatch oSB, float nScale) {
        for (int i = 0; i < CFG.NUM_OF_PROVINCES_IN_VIEW; ++i) {
            if (this.getProv(this.getPIV(i)).getCivId() == 0) continue;
            try {
                if (CFG.core.getProv(this.getPIV(i)).getCores().getCivsSize() <= 1) continue;
                this.drawCivilization_Flag_Cores(oSB, this.getPIV(i), nScale);
                continue;
            }
            catch (NullPointerException ex) {
                if (!CFG.LOGs) continue;
                CFG.exceptionStack(ex);
            }
        }
    }

