    public boolean getDrawProvinceNames() {
        return CFG.settingsGD.SPROVN > 1 && CFG.map.getMapProvinceNames(CFG.map.getActiveMapIDN());
    }

    public boolean getDrawProvinceCitiesNames() {
        return CFG.settingsGD.SPROVN == 1 || !CFG.map.getMapProvinceNames(CFG.map.getActiveMapIDN()) && CFG.settingsGD.SPROVN > 0;
    }

    public final void drawCities(SpriteBatch oSB, float nScale) {
        if (this.getDrawProvinceNames()) {
            try {
                oSB.setColor(Color.WHITE);
                CFG.core.drawWonders_FogOfWarDiscovery(oSB, nScale);
                for (int i = 0; i < CFG.NUM_OF_PROVINCES_IN_VIEW; ++i) {
                    if (!this.getProv(this.getPIV(i)).getDrawCitiesInProv()) continue;
                    for (int j = 0; j < this.getProv(this.getPIV(i)).getCitSize(); ++j) {
                        this.getProv(this.getPIV(i)).getCit(j).draw(oSB, this.getPIV(i), nScale);
                    }
                }
            }
            catch (Exception i) {
                
            }
            CFG.fontMain.get(0).getData().setScale(1.0f);
        } else if (this.getDrawProvinceCitiesNames()) {
            try {
                oSB.setColor(Color.WHITE);
                CFG.core.drawWonders_FogOfWarDiscovery(oSB, nScale);
                CFG.fontMain.get(0).getData().setScale(CFG.settingsGD.CITIES_FONT_SCALE);
                for (int i = 0; i < CFG.NUM_OF_PROVINCES_IN_VIEW; ++i) {
                    if (!this.getProv(this.getPIV(i)).getDrawCitiesInProv()) continue;
                    for (int j = 0; j < this.getProv(this.getPIV(i)).getCitSize(); ++j) {
                        this.getProv(this.getPIV(i)).getCit(j).drawWithName(oSB, this.getPIV(i), nScale);
                    }
                }
            }
            catch (Exception exception) {
                
            }
            CFG.fontMain.get(0).getData().setScale(1.0f);
        }
    }

