    public final void updatePath() {
        if (this.lMoveUnitsLineTime < System.currentTimeMillis() - 90L) {
            this.lMoveUnitsLineTime = System.currentTimeMillis();
            MoveUnits_Line_Highlighted.MOVE_SRC_X2 = MoveUnits_Line_Highlighted.MOVE_SRC_X2 <= 1 ? MoveUnits_Line_Highlighted.MOVE_WIDTH2 : --MoveUnits_Line_Highlighted.MOVE_SRC_X2;
            MoveUnits_Line.MOVE_SRC_X = MoveUnits_Line.MOVE_SRC_X <= 1 ? MoveUnits_Line.MOVE_WIDTH : --MoveUnits_Line.MOVE_SRC_X;
            MoveUnits_Line_Migrate.MOVE_SRC_X2 = MoveUnits_Line_Migrate.MOVE_SRC_X2 <= 1 ? MoveUnits_Line_Migrate.MOVE_WIDTH2 : --MoveUnits_Line_Migrate.MOVE_SRC_X2;
        }
    }

    public final void buildMoveUnits_JustDraw_AnotherArmies() {
        block5: {
            this.clearMoveUnits_JustDraw_AnotherArmies();
            try {
                int tPlayerCivID = CFG.SPECTATOR_MODE ? 0 : CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId();
                int tPlayerAllianceID = CFG.SPECTATOR_MODE || CFG.core.getCiv(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()).getAlliance() == 0 ? -1 : CFG.core.getCiv(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()).getAlliance();
                for (int i = 1; i < CFG.core.getCivsSize(); ++i) {
                    if (CFG.core.getCiv(i).getNumOfProvs() <= 0 || i == tPlayerCivID || CFG.core.getCiv(i).getAlliance() == tPlayerAllianceID || CFG.core.getCiv(i).getPuppetOfCiv() == tPlayerCivID || CFG.core.getCiv(tPlayerCivID).getPuppetOfCiv() == i) continue;
                    for (int j = 0; j < CFG.core.getCiv(i).moveUnitsSize(); ++j) {
                        int fromProvID = CFG.core.getCiv(i).getMoveUnits(j).getFromProviID();
                        int toProvID = CFG.core.getCiv(i).getMoveUnits(j).getToProvID();
                        boolean fromFog = CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getFog(fromProvID);
                        boolean toFog = CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getFog(toProvID);
                        boolean isSea = CFG.core.getProv(fromProvID).getSeaProv();
                        if (!fromFog && !toFog) continue;
                        if (isSea) {
                            this.lMoveUnits_JustDraw_AnotherArmies.add(new MoveUnits_JustDraw(i, CFG.core.getCiv(i).getMoveUnits(j)));
                            continue;
                        }
                        if (CFG.SANDBOX_MODE || CFG.SPECTATOR_MODE) {
                            this.lMoveUnits_JustDraw_AnotherArmies.add(new MoveUnits_JustDraw(i, CFG.core.getCiv(i).getMoveUnits(j)));
                            continue;
                        }
                        if (CFG.core.getCivsAtWar(tPlayerCivID, i) || !CFG.core.isAlly(tPlayerCivID, CFG.core.getProv(fromProvID).getCivId()) && !CFG.core.isAlly(tPlayerCivID, CFG.core.getProv(toProvID).getCivId())) continue;
                        this.lMoveUnits_JustDraw_AnotherArmies.add(new MoveUnits_JustDraw(i, CFG.core.getCiv(i).getMoveUnits(j)));
                    }
                }
            }
            catch (Exception ex) {
                if (!CFG.LOGs) break block5;
                CFG.exceptionStack(ex);
            }
        }
        this.iMoveUnits_JustDraw_AnotherArmiesSize = this.lMoveUnits_JustDraw_AnotherArmies.size();
    }

    public final void clearMoveUnits_JustDraw_AnotherArmies() {
        this.lMoveUnits_JustDraw_AnotherArmies.clear();
        this.iMoveUnits_JustDraw_AnotherArmiesSize = 0;
    }

