    public final void drawMoveUnits_Spectactor(SpriteBatch oSB, float nScale) {
        oSB.setColor(Color.WHITE);
        try {
            this.drawMoveUnitsArmy_UpdateAnimation = false;
            for (int i = 1; i < this.getCivsSize(); ++i) {
                int j;
                if (this.getCiv(i).getNumOfProvs() <= 0) continue;
                oSB.setColor(this.getCiv(i).getRGB());
                for (j = 0; j < this.getCiv(i).getRegroupArmySize(); ++j) {
                    for (int k = this.getCiv(i).getCurrentRegroupArmyLine(j).size() - 1; k >= 0; --k) {
                        if (this.getProv(this.getCiv(i).getCurrentRegroupArmyLine(j).get(k).getFromProvinceID()).getDrawProv()) {
                            this.getCiv(i).getCurrentRegroupArmyLine(j).get(k).drawLine(oSB, nScale);
                            continue;
                        }
                        if (!this.getProv(this.getCiv(i).getCurrentRegroupArmyLine(j).get(k).getFromProvinceID()).getDrawProv()) continue;
                        this.updateDrawProvince(this.getCiv(i).getMoveUnits(j).getFromProviID());
                        this.getCiv(i).getCurrentRegroupArmyLine(j).get(k).drawLine(oSB, nScale);
                    }
                }
                for (j = 0; j < this.getCiv(i).moveUnitsSize(); ++j) {
                    oSB.setColor(this.getCiv(i).getRGB());
                    if (this.getProv(this.getCiv(i).getMoveUnits(j).getFromProviID()).getDrawProv()) {
                        this.getCiv(i).getMoveUnits(j).draw2(oSB, nScale);
                        this.drawMoveUnitsFlag(oSB, i, this.getCiv(i).getMoveUnits(j).getToProvID(), nScale, this.getCiv(i).getMoveUnits(j).getMoveUnits_Line().getMovingPercentage());
                    } else if (this.getProv(this.getCiv(i).getMoveUnits(j).getToProvID()).getDrawProv()) {
                        this.updateDrawProvince(this.getCiv(i).getMoveUnits(j).getFromProviID());
                        this.getCiv(i).getMoveUnits(j).draw2(oSB, nScale);
                        this.drawMoveUnitsFlag(oSB, i, this.getCiv(i).getMoveUnits(j).getToProvID(), nScale, this.getCiv(i).getMoveUnits(j).getMoveUnits_Line().getMovingPercentage());
                    }
                    this.drawMoveUnitsArmy_UpdateAnimation = true;
                }
            }
        }
        catch (Exception exception) {
            
        }
    }

