    public final void setChosenProvinceID(int nProvinceID) {
        if (CFG.migrateMode) {
            CFG.gameAction.hideAllViews();
            CFG.menus.rebuildInGame_Migrate(CFG.core.getActiveProvID(), nProvinceID);
            this.resetChooseProvinceData_Immediately();
            CFG.core.setActiveProvID(nProvinceID);
        } else {
            int moveCivID = CFG.gameAction.getControlledArmyCivIDInProvince(this.getActiveProvID(), CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId());
            if (CFG.chosenProvinceID < 0) {
                CFG.gameAction.hideAllViews();
                CFG.menus.getInGame_ProvinceMoveUnits_Slider().setMax(this.getProv(this.getActiveProvID()).getArmyCivID1(moveCivID));
                CFG.menus.getInGame_ProvinceMoveUnits_Slider().setCurr(this.getProv(this.getActiveProvID()).getArmyCivID1(moveCivID));
                CFG.menus.setVisible_InGame_ProvinceMoveUnits(true);
            } else if (CFG.chosenProvinceID == nProvinceID && CFG.menus.getInGame_ProvinceMoveUnits_Visible()) {
                CFG.menus.getInGame_ProvinceMoveUnits_Confrim();
                CFG.SFXManager.playSound(SFXManager.SFX_MOVE_ARMY);
                CFG.map.getTouchMgr().setActionDownTime(0L);
                return;
            }
            CFG.chosenProvinceID = nProvinceID;
            this.updateProvNameWidth(CFG.chosenProvinceID);
            boolean tFound = false;
            for (int i = 0; i < this.getCiv(moveCivID).moveUnitsSize(); ++i) {
                if (this.getCiv(moveCivID).getMoveUnits(i).getFromProviID() != this.getActiveProvID() || this.getCiv(moveCivID).getMoveUnits(i).getToProvID() != CFG.chosenProvinceID) continue;
                CFG.menus.getInGame_ProvinceMoveUnits_Slider().setMax(this.getProv(this.getActiveProvID()).getArmyCivID1(moveCivID) + this.getCiv(moveCivID).getMoveUnits(i).getNumberOfUnits());
                CFG.menus.getInGame_ProvinceMoveUnits_Slider().setCurr(this.getCiv(moveCivID).getMoveUnits(i).getNumberOfUnits());
                tFound = true;
                break;
            }
            if (!tFound) {
                CFG.menus.getInGame_ProvinceMoveUnits_Slider().setMax(this.getProv(this.getActiveProvID()).getArmyCivID1(moveCivID));
                CFG.menus.getInGame_ProvinceMoveUnits_Slider().setCurr(this.getProv(this.getActiveProvID()).getArmyCivID1(moveCivID));
            }
            this.currMoveUnitsLine = new MoveUnits_Line_Current(this.getActiveProvID(), nProvinceID);
            CFG.gameAction.updateInGame_ProvinceInfo();
            CFG.menus.setVisible_InGame_ActionInfo_Move();
        }
    }

    public final void setCurrentRegroupArmyID(int nToProvinceID) {
        int moveFromProvinceID = this.getActiveProvID();
        int playerCivID = CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId();
        int moveCivID = CFG.gameAction.getControlledArmyCivIDInProvince(moveFromProvinceID, playerCivID);
        if (this.getProv(moveFromProvinceID).getArmyCivID1(moveCivID) == 0) {
            CFG.map.getTouchMgr();
            if (TouchManager.lMABX.size() > 0) {
                CFG.map.getTouchMgr();
                this.setActiveProvID(TouchManager.lMABX.get(0));
                moveFromProvinceID = this.getActiveProvID();
                moveCivID = CFG.gameAction.getControlledArmyCivIDInProvince(moveFromProvinceID, playerCivID);
            }
        }
        if (CFG.chosenProvinceID < 0) {
            CFG.gameAction.hideAllViews();
            CFG.menus.getInGame_RegroupArmy_Slider().setMax(this.getProv(moveFromProvinceID).getArmyCivID1(moveCivID));
            CFG.menus.getInGame_RegroupArmy_Slider().setCurr(this.getProv(moveFromProvinceID).getArmyCivID1(moveCivID));
            CFG.menus.setVisible_InGame_ProvinceRegroupArmy(true);
        }
        this.currentRegroupArmy = null;
        if (!GameManager.canMoveToNeighbooringProvince(nToProvinceID, CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId())) {
            CFG.gameAction.hideAllViews();
            this.currentRegroupArmyLine.clear();
            CFG.chosenProvinceID = -1;
            CFG.menus.setVisible_InGame_ActionInfo_RegroupArmy();
            return;
        }
        if (!TouchManager.lMABX.isEmpty() && TouchManager.lMABX.size() > 1) {
            this.currentRegroupArmyLine.clear();
            this.currentRegroupArmyLine = new ArrayList<MoveUnits_Line>();
            CFG.menus.setVisible_InGame_ProvinceAction(false);
            CFG.menus.setVisible_InGame_ProvinceAction_Colonize(false);
            CFG.menus.setVisible_InGame_ProvinceAction_Colonize_TechRequired(false);
            CFG.menus.setVisible_InGame_ProvinceRegroupArmy(false);
            CFG.menus.setVisible_InGame_ProvinceAction_Nuke(false);
            for (int i = 0; i < TouchManager.lMABX.size(); ++i) {
                int boxMoveCivID = CFG.gameAction.getControlledArmyCivIDInProvince(TouchManager.lMABX.get(i), playerCivID);
                int boxRouteCivID = CFG.gameAction.getArmyMovementPayerCivID(TouchManager.lMABX.get(i), boxMoveCivID);
                RegroupArmy nRegroup = new RegroupArmy(boxRouteCivID, TouchManager.lMABX.get(i), nToProvinceID);
                if (nRegroup.getRouteSize() <= 0) continue;
                CFG.chosenProvinceID = nToProvinceID;
                this.currentRegroupArmyLine.add(new MoveUnits_Line_Current(nRegroup.getFromProvinceID(), nRegroup.getRoute(0)));
                for (int j = 0; j < nRegroup.getRouteSize() - 1; ++j) {
                    this.currentRegroupArmyLine.add(new MoveUnits_Line_Highlighted(nRegroup.getRoute(j), nRegroup.getRoute(j + 1)));
                }
                if (this.currentRegroupArmy == null) {
                    this.currentRegroupArmy = nRegroup;
                }
                this.updateProvNameWidth(CFG.chosenProvinceID);
                CFG.gameAction.updateInGame_ProvinceInfo();
            }
            if (this.currentRegroupArmy == null) {
                CFG.gameAction.hideAllViews();
                this.currentRegroupArmyLine.clear();
                CFG.chosenProvinceID = -1;
                CFG.menus.setVisible_InGame_ActionInfo_RegroupArmy();
            } else {
                CFG.menus.setVisible_InGame_ActionInfo_RegroupArmy_Confirm();
            }
        } else {
            int routeCivID = CFG.gameAction.getArmyMovementPayerCivID(moveFromProvinceID, moveCivID);
            this.currentRegroupArmy = new RegroupArmy(routeCivID, moveFromProvinceID, nToProvinceID);
            if (this.currentRegroupArmy.getRouteSize() > 0) {
                CFG.chosenProvinceID = nToProvinceID;
                CFG.addRemoveChosenProvinceRegroup(CFG.chosenProvinceID);
                this.currentRegroupArmyLine.clear();
                this.currentRegroupArmyLine = new ArrayList<MoveUnits_Line>();
                if (CFG.chosenProvinces_Regroup.size() > 0) {
                    for (int a = 0; a < CFG.chosenProvinces_Regroup.size(); ++a) {
                        try {
                            RegroupArmy regroupArmyData = new RegroupArmy(routeCivID, moveFromProvinceID, CFG.chosenProvinces_Regroup.get(a));
                            if (regroupArmyData.getRouteSize() <= 0) continue;
                            this.currentRegroupArmyLine.add(new MoveUnits_Line_Current(regroupArmyData.getFromProvinceID(), regroupArmyData.getRoute(0)));
                            for (int i = 0; i < regroupArmyData.getRouteSize() - 1; ++i) {
                                this.currentRegroupArmyLine.add(new MoveUnits_Line_Highlighted(regroupArmyData.getRoute(i), regroupArmyData.getRoute(i + 1)));
                            }
                            continue;
                        }
                        catch (Exception ex) {
                            CFG.exceptionStack(ex);
                        }
                    }
                } else {
                    this.currentRegroupArmyLine.add(new MoveUnits_Line_Current(this.currentRegroupArmy.getFromProvinceID(), this.currentRegroupArmy.getRoute(0)));
                    for (int i = 0; i < this.currentRegroupArmy.getRouteSize() - 1; ++i) {
                        this.currentRegroupArmyLine.add(new MoveUnits_Line_Highlighted(this.currentRegroupArmy.getRoute(i), this.currentRegroupArmy.getRoute(i + 1)));
                    }
                }
                this.updateProvNameWidth(CFG.chosenProvinceID);
                CFG.gameAction.updateInGame_ProvinceInfo();
                CFG.menus.setVisible_InGame_ActionInfo_RegroupArmy_Move();
            } else {
                CFG.gameAction.hideAllViews();
                this.currentRegroupArmyLine.clear();
                CFG.chosenProvinceID = -1;
                CFG.menus.setVisible_InGame_ActionInfo_RegroupArmy();
            }
        }
    }

    public final void autoBuildChooseProvinceMode(boolean force) {
        if (CFG.gameAction.getActiveTurnStateID() == GameAction.TurnStates.INPUT_ORDERS && !CFG.chooseProvinceMode && CFG.map.getMpS().getCurrSc() >= 1.0f && (CFG.activeProvince_BEFORE != this.getActiveProvID() && !CFG.menus.getInGame_ProvincemMore_Visible() || force) && (CFG.mapModesManager.getActiveMapModeID() < 0 || CFG.mapModesManager.getActiveView().canMoveArmy()) && !this.getProv(this.getActiveProvID()).getSeaProv() && this.getProv(this.getActiveProvID()).getWastelandLvl() < 0 && CFG.gameAction.controlsArmyInProvince(this.getActiveProvID())) {
            this.autoChooseProvinceMode(this.getActiveProvID());
        }
    }

    private final void autoChooseProvinceMode(int nProvinceID) {
        if (CFG.regroupArmyMode || CFG.menus.getVisible_InGame_FlagAction() || !AMRCT.isEmpty()) {
            return;
        }
        this.currMoveUnitsLine = null;
        if (this.getActiveProvID() < 0) {
            return;
        }
        CFG.activeCivilizationArmyID = Math.max(0, CFG.gameAction.getControlledArmyIDInProvince(this.getActiveProvID(), CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()));
        this.highlightedProvinceBorder_BackAnimation = false;
        CFG.chooseProvinceMode = true;
        CFG.chosenProvinceID = -1;
        this.updateHighlight_MoveUnitsProvinces(nProvinceID);
    }

    public final void chooseProvinceMode() {
        if (CFG.regroupArmyMode) {
            this.resetRegroupArmy_Data();
        }
        this.autoChooseProvinceMode(this.getActiveProvID());
        if (this.getActiveProvID() < 0) {
            return;
        }
        CFG.menus.setVisible_InGame_ActionInfo_ChooseProvince();
        this.HIGHLIGHTED_CITIES_DISABLE_ANIMATION = false;
        this.lTIME_HIGHLIGHTED_CITIES = System.currentTimeMillis();
    }

