    public final void buildWars() {
        this.lWars = new ArrayList<War_GameData>();
        this.iWarsSize = 0;
        this.lPeaceTreaties = new ArrayList<PeaceTreaty_GameData_MessageData>();
        this.invalidateWarCache();
    }

    public final void invalidateWarCache() {
        this.warScoreCacheTurn = -1;
        this.warScoreCache.clear();
        this.warIndexCache.clear();
    }

    public final int getCachedWarScore(War_GameData war) {
        if (this.warScoreCacheTurn != GameCalendar.TURNID) {
            this.warScoreCache.clear();
            this.warScoreCacheTurn = GameCalendar.TURNID;
        }
        Integer cached = this.warScoreCache.get(war.WAR_TAG);
        if (cached != null) return cached.intValue();
        int score = war.getWarScore();
        this.warScoreCache.put(war.WAR_TAG, Integer.valueOf(score));
        return score;
    }

    public final int getWarIndex(int iCivA, int iCivB) {
        String key = iCivA + "_" + iCivB;
        Integer cached = this.warIndexCache.get(key);
        if (cached != null) {
            if (cached.intValue() >= 0 && cached.intValue() < this.getWarsSize()) {
                War_GameData w = this.lWars.get(cached.intValue());
                if (w.getIsInAggressors(iCivA) && w.getIsInDefenders(iCivB) || w.getIsInDefenders(iCivA) && w.getIsInAggressors(iCivB)) {
                    return cached.intValue();
                }
            }
        }
        for (int i = 0; i < this.getWarsSize(); ++i) {
            War_GameData w = this.lWars.get(i);
            if (w.getIsInAggressors(iCivA) && w.getIsInDefenders(iCivB) || w.getIsInDefenders(iCivA) && w.getIsInAggressors(iCivB)) {
                this.warIndexCache.put(key, Integer.valueOf(i));
                return i;
            }
        }
        this.warIndexCache.put(key, Integer.valueOf(-1));
        return -1;
    }

