    private final void acceptPeaceForWar(int nWarID) {
        try {
            for (int d = 0; d < this.lWars.get(nWarID).getDefendersSize(); ++d) {
                int defenderID = this.lWars.get(nWarID).getDefenderID(d).getCivID();
                for (int a = 0; a < this.lWars.get(nWarID).getAggressorsSize(); ++a) {
                    int aggressorID = this.lWars.get(nWarID).getAggressorID(a).getCivID();
                    if (!this.getCivsAtWar(defenderID, aggressorID)) continue;
                    this.acceptPeaceOffer(defenderID, aggressorID, GameValues.gvPeaceTreaty.PEACE_TREATY_DEFAULT_DURATION + 1);
                }
            }
        }
        catch (Exception ex) {
        }
    }

    public final void addWarData(int nAggressor, int nDefender) {
        int i;
        int j;
        if (nAggressor == 0 || nDefender == 0 || nAggressor == nDefender) {
            return;
        }
        for (i = 0; i < this.getWarsSize(); ++i) {
            War_GameData war = this.lWars.get(i);
            if (war.getIsInAggressors(nAggressor) && war.getIsInDefenders(nDefender)) return;
            if (war.getIsInAggressors(nDefender) && war.getIsInDefenders(nAggressor)) return;
        }
        
        
        if (this.getCivsAreAllied(nAggressor, nDefender) || this.getCiv(nAggressor).getPuppetOfCiv() == this.getCiv(nDefender).getPuppetOfCiv()) {
             return;
        }

        if (this.getCiv(nAggressor).getAlliance() > 0) {
            for (i = 0; i < this.getAlliance(this.getCiv(nAggressor).getAlliance()).getCivilizationsSize(); ++i) {
                if (this.getAlliance(this.getCiv(nAggressor).getAlliance()).getCivilization(i) == nAggressor) continue;
                for (j = 0; j < this.getWarsSize(); ++j) {
                    if (this.lWars.get(j).getIsAggressor(this.getAlliance(this.getCiv(nAggressor).getAlliance()).getCivilization(i))) {
                        if (!this.lWars.get(j).getIsDefender(nDefender)) continue;
                        this.lWars.get(j).addAggressor(nAggressor);
                        return;
                    }
                    if (!this.lWars.get(j).getIsDefender(this.getAlliance(this.getCiv(nAggressor).getAlliance()).getCivilization(i)) || !this.lWars.get(j).getIsAggressor(nDefender)) continue;
                    this.lWars.get(j).addDefender(nAggressor);
                    return;
                }
            }
        }
        if (this.getCiv(nDefender).getAlliance() > 0) {
            for (i = 0; i < this.getAlliance(this.getCiv(nDefender).getAlliance()).getCivilizationsSize(); ++i) {
                if (this.getAlliance(this.getCiv(nDefender).getAlliance()).getCivilization(i) == nDefender) continue;
                for (j = 0; j < this.getWarsSize(); ++j) {
                    if (this.lWars.get(j).getIsAggressor(this.getAlliance(this.getCiv(nDefender).getAlliance()).getCivilization(i))) {
                        if (!this.lWars.get(j).getIsDefender(nAggressor)) continue;
                        this.lWars.get(j).addAggressor(nDefender);
                        return;
                    }
                    if (!this.lWars.get(j).getIsDefender(this.getAlliance(this.getCiv(nDefender).getAlliance()).getCivilization(i)) || !this.lWars.get(j).getIsAggressor(nAggressor)) continue;
                    this.lWars.get(j).addDefender(nDefender);
                    return;
                }
            }
        }
        this.lWars.add(new War_GameData(nAggressor, nDefender));
        this.iWarsSize = this.lWars.size();
        this.invalidateWarCache();
    }

