    public final void setWasteland(int nProvinceID, boolean wasteland) {
        if (wasteland) {
            if (this.getProv(nProvinceID).getWastelandLvl() >= 0 != wasteland) {
                CFG.addUndoWastelandProvince(nProvinceID);
            }
            this.getProv(nProvinceID).setWastelandLvl(0);
            for (int i = 0; i < this.getProv(nProvinceID).getNeighProvincesSize(); ++i) {
                if (this.getProv(this.getProv(nProvinceID).getNeighProvinces(i)).getWastelandLvl() >= 0 || this.getProv(this.getProv(nProvinceID).getNeighProvinces(i)).getNeighSeaProvincesSize() > 0 && this.checkClosedSea(nProvinceID)) continue;
                ArrayList<Integer> nWastelandProvinces = new ArrayList<Integer>();
                nWastelandProvinces.add(this.getProv(nProvinceID).getNeighProvinces(i));
                this.getProv(this.getProv(nProvinceID).getNeighProvinces(i)).setWastelandLvl(0);
                this.breakWasteland = false;
                this.checkWastelandProvince(this.getProv(nProvinceID).getNeighProvinces(i), nWastelandProvinces);
            }
        } else if (this.getProv(nProvinceID).getNeighSeaProvincesSize() > 0 && this.checkClosedSea(nProvinceID)) {
            if (this.getProv(nProvinceID).getWastelandLvl() >= 0 != wasteland) {
                CFG.addUndoWastelandProvince(nProvinceID);
            }
            this.getProv(nProvinceID).setWastelandLvl(-1);
        } else {
            for (int i = 0; i < this.getProv(nProvinceID).getNeighProvincesSize(); ++i) {
                if (this.getProv(this.getProv(nProvinceID).getNeighProvinces(i)).getWastelandLvl() >= 0) continue;
                if (this.getProv(nProvinceID).getWastelandLvl() >= 0 != wasteland) {
                    CFG.addUndoWastelandProvince(nProvinceID);
                }
                this.getProv(nProvinceID).setWastelandLvl(-1);
                return;
            }
        }
    }

    private final void checkWastelandProvince(int nProvinceID, List<Integer> nWastelandProvinces) {
        if (this.breakWasteland) {
            for (int a = nWastelandProvinces.size() - 1; a >= 0; --a) {
                this.getProv(nWastelandProvinces.get(a)).setWastelandLvl(-1);
            }
            return;
        }
        for (int i = 0; i < this.getProv(nProvinceID).getNeighProvincesSize(); ++i) {
            if (this.getProv(this.getProv(nProvinceID).getNeighProvinces(i)).getWastelandLvl() >= 0) continue;
            if (this.getProv(this.getProv(nProvinceID).getNeighProvinces(i)).getNeighSeaProvincesSize() > 0 && this.checkClosedSea(nProvinceID)) {
                for (int a = nWastelandProvinces.size() - 1; a >= 0; --a) {
                    this.getProv(nWastelandProvinces.get(a)).setWastelandLvl(-1);
                }
                this.breakWasteland = true;
                continue;
            }
            this.getProv(this.getProv(nProvinceID).getNeighProvinces(i)).setWastelandLvl(0);
            nWastelandProvinces.add(this.getProv(nProvinceID).getNeighProvinces(i));
            this.checkWastelandProvince(this.getProv(nProvinceID).getNeighProvinces(i), nWastelandProvinces);
        }
    }

