    public final void saveScenario_OccupiedProvinces() {
        try {
            Province_GameData_Occupied occupied = new Province_GameData_Occupied();
            for (int i = 0; i < CFG.core.getProvinSize(); ++i) {
                if (CFG.core.getProv(i).getCivId() <= 0 || CFG.core.getProv(i).getCivId() == CFG.core.getProv(i).getTrueOwnerOfProv()) continue;
                occupied.addData(i, CFG.core.getProv(i).getTrueOwnerOfProv());
            }
            Json json = new Json();
            json.setOutputType(JsonWriter.OutputType.json);
            FileHandle fileOccupied = FileManager.getSaveType("map/" + CFG.map.getFileActiveMapPath() + "scenarios/" + CFG.CREATE_SCENARIO_GAME_DATA_TAG + "/" + CFG.CREATE_SCENARIO_GAME_DATA_TAG + "_O");
            fileOccupied.writeString(json.prettyPrint(occupied), false, "UTF-8");
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    private final void saveScenario_Info() {
        CFG.ConfigScenarioInfo configData = new CFG.ConfigScenarioInfo();
        configData.Age_of_Civilizations = "Data";
        ArrayList<CFG.Data_Scenario_Info> dataList = new ArrayList<CFG.Data_Scenario_Info>();
        dataList = new ArrayList();
        int tNumOfCivs = 0;
        for (int i = 1; i < CFG.core.getCivsSize(); ++i) {
            if (CFG.core.getCiv(i).getNumOfProvs() <= 0) continue;
            ++tNumOfCivs;
        }
        CFG.Data_Scenario_Info nDataTag = new CFG.Data_Scenario_Info();
        nDataTag.Name = CFG.CREATE_SCENARIO_NAME;
        nDataTag.Civs = tNumOfCivs;
        nDataTag.Author = CFG.CREATE_SCENARIO_AUTHOR;
        nDataTag.Wiki = CFG.CREATE_SCENARIO_WIKI;
        nDataTag.Age = CFG.gameAges.getAgeOfYear(GameCalendar.currYear);
        nDataTag.Year = GameCalendar.currYear;
        nDataTag.Month = GameCalendar.currMonth;
        nDataTag.Day = GameCalendar.currDay;
        dataList.add(nDataTag);
        configData.Data_Scenario_Info = dataList;
        Json jsonSave = new Json();
        jsonSave.setOutputType(JsonWriter.OutputType.json);
        jsonSave.setElementType(CFG.ConfigScenarioInfo.class, "Data_Scenario_Info", CFG.Data_Scenario_Info.class);
        FileHandle fileSave = FileManager.getSaveType("map/" + CFG.map.getFileActiveMapPath() + "scenarios/" + CFG.CREATE_SCENARIO_GAME_DATA_TAG + "/" + CFG.CREATE_SCENARIO_GAME_DATA_TAG + "_INFO" + ".json");
        if (!fileSave.parent().exists()) {
            fileSave.parent().mkdirs();
        }
        fileSave.writeString(jsonSave.prettyPrint(configData), false);
    }

