    public final void saveCityInGame() {
        try {
            CFG.core.getPlayer((int)CFG.PLAYER_TURN_ID).playerGD.cts.add(CFG.editorCity);
            for (int j = 0; j < CFG.core.getProvinSize(); ++j) {
                if (this.getProv(j).getMiX2() > CFG.editorCity.getPoX() * CFG.map.getMpB().getMapSc3() || this.getProv(j).getMaX7() < CFG.editorCity.getPoX() * CFG.map.getMpB().getMapSc3() || this.getProv(j).getMiY4() > CFG.editorCity.getPosY() * CFG.map.getMpB().getMapSc3() || this.getProv(j).getMaY6() < CFG.editorCity.getPosY() * CFG.map.getMpB().getMapSc3() || !this.ptCS(j, CFG.editorCity.getPoX() * CFG.map.getMpB().getMapSc3(), CFG.editorCity.getPosY() * CFG.map.getMpB().getMapSc3())) continue;
                this.getProv(j).addCityRename(CFG.editorCity);
                break;
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public void loadCitiesInGame() {
        for (int a = 0; a < this.getPlayersSize(); ++a) {
            block1: for (int b = 0; b < this.getPlayer((int)a).playerGD.cts.size(); ++b) {
                for (int j = 0; j < CFG.core.getProvinSize(); ++j) {
                    if (this.getProv(j).getMiX2() > this.getPlayer((int)a).playerGD.cts.get(b).getPoX() * CFG.map.getMpB().getMapSc3() || this.getProv(j).getMaX7() < this.getPlayer((int)a).playerGD.cts.get(b).getPoX() * CFG.map.getMpB().getMapSc3() || this.getProv(j).getMiY4() > this.getPlayer((int)a).playerGD.cts.get(b).getPosY() * CFG.map.getMpB().getMapSc3() || this.getProv(j).getMaY6() < this.getPlayer((int)a).playerGD.cts.get(b).getPosY() * CFG.map.getMpB().getMapSc3() || !this.ptCS(j, this.getPlayer((int)a).playerGD.cts.get(b).getPoX() * CFG.map.getMpB().getMapSc3(), this.getPlayer((int)a).playerGD.cts.get(b).getPosY() * CFG.map.getMpB().getMapSc3())) continue;
                    this.getProv(j).addCityRename(this.getPlayer((int)a).playerGD.cts.get(b));
                    continue block1;
                }
            }
        }
    }

    public final int getProvinceArmy(int nProvinceID) {
        int out = 0;
        Province province = this.getProv(nProvinceID);
        for (int i = 0; i < province.getCivsSize(); ++i) {
            out += province.getArmyID(i);
        }
        return out;
    }

    public final int getProvinceValue(int nProvinceID) {
        int out = GameValues.gvProvinceValue.BASE_PROVINCE_VALUE;
        out += this.getProvinceValue_Terrain(nProvinceID);
        out += this.getProvinceValue_Capital(nProvinceID);
        out += this.getProvinceValue_PopulationGrowthRate(nProvinceID);
        return out += this.getProvinceValue_DevelopmentLevel(nProvinceID);
    }

    public final int getProvinceValue_Terrain(int nProvinceID) {
        return CFG.terrainTypesManager.getBaseProvinceValue(this.getProv(nProvinceID).getTerrainTypeID());
    }

    public final int getProvinceValue_Capital(int nProvinceID) {
        return this.getProv(nProvinceID).isCapital() ? GameValues.gvProvinceValue.BASE_PROVINCE_VALUE_CAPITAL : 0;
    }

    public final int getProvinceValue_PopulationGrowthRate(int nProvinceID) {
        return (int)(this.getProv(nProvinceID).getGrowthRate_Pop_WithFarm() * GameValues.gvProvinceValue.PROVINCE_VALUE_GROWTH_RATE_MODIFIER);
    }

    public final int getProvinceValue_DevelopmentLevel(int nProvinceID) {
        return (int)(Math.min(GameValues.gvProvinceValue.PROVINCE_VALUE_DEVELOPMENT_MAX, this.getProv(nProvinceID).getDeveLvl()) * GameValues.gvProvinceValue.PROVINCE_VALUE_DEVELOPMENT_MODIFIER);
    }

    public final Province getProv(int ID) {
        return this.lProvs.get(ID);
    }

    public final int getProvinSize() {
        return this.iProvincesSize;
    }

    public static void addDiplomacyLines(int iProvinceA, int iProvinceB, Color nColor) {
        try {
            if (iProvinceA < 0 || iProvinceB < 0) {
                return;
            }
            if (iDiplomacyLinesSize > (CFG.getIsDesktop() ? GameValues.gvInGame.MAP_LINES_LIMIT : GameValues.gvInGame.MAP_LINES_LIMIT_MOBILE)) {
                return;
            }
            if ((CFG.core.getProv(iProvinceA).getDrawProv() || CFG.core.getProv(iProvinceB).getDrawProv()) && CFG.map.getMpS().getCurrSc() > DRAW_INNER_BORDERS) {
                for (int i = diplomacyLines.size() - 1; i >= 0; --i) {
                    if (diplomacyLines.get(i).getFromProvinceID() != iProvinceA || diplomacyLines.get(i).getToProvinceLastID() != iProvinceB) continue;
                    return;
                }
                MoveUnits_DiplomacyLines nLine = new MoveUnits_DiplomacyLines(CFG.core.getProv(iProvinceA).getCivId(), iProvinceA, iProvinceB, nColor){

                    @Override
                    public boolean isFriendlyProvince(int nCivID, int toProvinceID) {
                        return true;
                    }

                    @Override
                    public boolean canBeUsedInPath(int nCivID, int nProvinceID, boolean moveToFriendlyProvince, int toProvinceID) {
                        return CFG.core.getProv(nProvinceID).getWastelandLvl() < 0;
                    }
                };
                if (nLine.iRouteSize > 0) {
                    synchronized (diplomacyLines) {
                        diplomacyLines.add(nLine);
                        iDiplomacyLinesSize = diplomacyLines.size();
                    }
                }
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public static void addDiplomacyLines(int iProvinceA, int iProvinceB, Color nColor, Color nColor2) {
        try {
            if (iProvinceA < 0 || iProvinceB < 0) {
                return;
            }
            if (iDiplomacyLinesSize > (CFG.getIsDesktop() ? GameValues.gvInGame.MAP_LINES_LIMIT : GameValues.gvInGame.MAP_LINES_LIMIT_MOBILE)) {
                return;
            }
            if ((CFG.core.getProv(iProvinceA).getDrawProv() || CFG.core.getProv(iProvinceB).getDrawProv()) && CFG.map.getMpS().getCurrSc() > DRAW_INNER_BORDERS) {
                for (int i = diplomacyLines.size() - 1; i >= 0; --i) {
                    if (diplomacyLines.get(i).getFromProvinceID() != iProvinceA || diplomacyLines.get(i).getToProvinceLastID() != iProvinceB) continue;
                    return;
                }
                MoveUnits_DiplomacyLines nLine = new MoveUnits_DiplomacyLines(CFG.core.getProv(iProvinceA).getCivId(), iProvinceA, iProvinceB, CFG.core.getCiv(CFG.core.getProv(iProvinceA).getCivId()).getRGB(), CFG.core.getCiv(CFG.core.getProv(iProvinceB).getCivId()).getRGB()){

                    @Override
                    public boolean isFriendlyProvince(int nCivID, int toProvinceID) {
                        return true;
                    }

                    @Override
                    public boolean canBeUsedInPath(int nCivID, int nProvinceID, boolean moveToFriendlyProvince, int toProvinceID) {
                        return CFG.core.getProv(nProvinceID).getWastelandLvl() < 0;
                    }
                };
                if (nLine.iRouteSize > 0) {
                    synchronized (diplomacyLines) {
                        diplomacyLines.add(nLine);
                        iDiplomacyLinesSize = diplomacyLines.size();
                    }
                }
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public static void drawDiplomacyLines_Just(SpriteBatch oSB, float nScale) {
        if (iDiplomacyLinesSize > 0) {
            try {
                int j;
                oSB.setColor(Color.WHITE);
                for (j = iDiplomacyLinesSize - 1; j >= 0; --j) {
                    try {
                        diplomacyLines.get(j).update();
                        continue;
                    }
                    catch (Exception ex) {
                        diplomacyLines.remove(j);
                        CFG.exceptionStack(ex);
                    }
                }
                try {
                    for (j = iDiplomacyLinesSize - 1; j >= 0; --j) {
                        try {
                            if (!diplomacyLines.get(j).draw(oSB, nScale)) continue;
                            diplomacyLines.remove(j);
                            continue;
                        }
                        catch (Exception ex) {
                            diplomacyLines.remove(j);
                            CFG.exceptionStack(ex);
                        }
                    }
                    iDiplomacyLinesSize = diplomacyLines.size();
                }
                catch (Exception ex) {
                    CFG.exceptionStack(ex);
                }
            }
            catch (Exception ex) {
                CFG.exceptionStack(ex);
            }
            try {
                Renderer.oSBBorder2.end();
            }
            catch (Exception ex) {
                CFG.exceptionStack(ex);
            }
            try {
                Renderer.oSBBorder2.begin();
            }
            catch (Exception exception) {
                
            }
        }
    }

    public static void clearDiplomacyLines() {
        diplomacyLines.clear();
        iDiplomacyLinesSize = 0;
    }

