    public final int countLandProvinces_NotWasteland() {
        int out = 0;
        for (int i = 0; i < this.getProvinSize(); ++i) {
            if (this.getProv(i).getSeaProv() || this.getProv(i).getWastelandLvl() >= 0) continue;
            ++out;
        }
        return out;
    }

    public final int countLandProvinces() {
        int out = 0;
        for (int i = 0; i < this.getProvinSize(); ++i) {
            if (this.getProv(i).getSeaProv()) continue;
            ++out;
        }
        return out;
    }

    public static void dARA(long tRAT) {
        try {
            for (AMR res : AMRCT) {
                res.SPR = 0;
            }
            while (tRAT > 0) {
                ArrayList<AMR> xRS = new ArrayList<AMR>();
                for (AMR res : AMRCT) {
                    if (res.SPR >= res.ILM) continue;
                    xRS.add(res);
                }
                if (!xRS.isEmpty()) {
                    int tYRA = xRS.size();
                    long share = tRAT / (long)tYRA;
                    if (share == 0L) {
                        share = 1L;
                    }
                    boolean BTRD = false;
                    for (AMR ram : xRS) {
                        long INGR = (long)ram.ILM - (long)ram.SPR;
                        long DAT = Math.min(share, INGR);
                        ram.SPR = (int)((long)ram.SPR + DAT);
                        tRAT -= DAT;
                        if (DAT <= 0L) continue;
                        BTRD = true;
                    }
                    if (BTRD) continue;
                }
                break;
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public static void dARA(int tRAT) {
        Core.dARA((long)tRAT);
    }

