                int i;
                long tempTotalPop = CFG.core.getCiv(nCivID).countPop();
                nData.add(new ME_Hover_2Type_Text_Big(CFG.lang.get("Population") + ": "));
                nData.add(new ME_Hover_2Type_Text_Big("" + CFG.getNumberWthSpaces("" + tempTotalPop), CFG.COLOR_POPULATION));
