    public final ME_Hover_v2 getHover_PopulationOfCiv_CreateAVassal() {
        try {
            int i;
            ArrayList<MEHover_2E> nElements = new ArrayList<MEHover_2E>();
            ArrayList<ME_Hover_2Type> nData = new ArrayList<ME_Hover_2Type>();
            int tempTotalPop = 0;
            for (int i2 = 0; i2 < this.getProvSelected().getProvSize(); ++i2) {
                tempTotalPop += this.getProv(this.getProvSelected().getProv(i2)).getPop().getPops();
            }
            nData.add(new ME_Hover_2Type_Text(CFG.lang.get("Population") + ": "));
            nData.add(new ME_Hover_2Type_Text("" + CFG.getNumberWthSpaces("" + tempTotalPop), CFG.COLOR_POPULATION));
            nData.add(new ME_Hover_2Type_Image(Images.pop, CFG.PADD, 0));
            nElements.add(new MEHover_2E(nData));
            nData.clear();
            ArrayList<Integer> tempNat = new ArrayList<Integer>();
            ArrayList<Integer> tempNum = new ArrayList<Integer>();
            for (int i3 = 0; i3 < this.getProvSelected().getProvSize(); ++i3) {
                for (int j = 0; j < CFG.core.getProv(this.getProvSelected().getProv(i3)).getPop().getNatsSize(); ++j) {
                    boolean addNew = true;
                    for (int k = 0; k < tempNat.size(); ++k) {
                        if (((Integer)tempNat.get(k)).intValue() != CFG.core.getProv(this.getProvSelected().getProv(i3)).getPop().getCivID(j)) continue;
                        tempNum.set(k, (Integer)tempNum.get(k) + (int)CFG.core.getProv(this.getProvSelected().getProv(i3)).getPop().getPopulationID(j));
                        addNew = false;
                        break;
                    }
                    if (!addNew) continue;
                    tempNat.add(CFG.core.getProv(this.getProvSelected().getProv(i3)).getPop().getCivID(j));
                    tempNum.add((int)CFG.core.getProv(this.getProvSelected().getProv(i3)).getPop().getPopulationID(j));
                }
            }
            ArrayList<Integer> tempSortedNat = new ArrayList<Integer>();
            ArrayList<Integer> tempSortedNum = new ArrayList<Integer>();
            while (tempNat.size() > 0) {
                int nMax = 0;
                for (int i4 = 1; i4 < tempNat.size(); ++i4) {
                    if ((Integer)tempNum.get(nMax) >= (Integer)tempNum.get(i4)) continue;
                    nMax = i4;
                }
                tempSortedNat.add((Integer)tempNat.get(nMax));
                tempSortedNum.add((Integer)tempNum.get(nMax));
                tempNat.remove(nMax);
                tempNum.remove(nMax);
            }
            if (CFG.menus.getInGameView() && CFG.FOG_OF_WAR == 2) {
                for (i = 0; i < tempSortedNat.size(); ++i) {
                    nData.add(new ME_Hover_2Type_Flag(CFG.getMetCiv((Integer)tempSortedNat.get(i)) ? (Integer)tempSortedNat.get(i) : -1));
                    nData.add(new ME_Hover_2Type_Text("" + CFG.getNumberWthSpaces("" + tempSortedNum.get(i)), CFG.COLOR_POPULATION));
                    nData.add(new ME_Hover_2Type_Image(Images.pop, CFG.PADD, CFG.PADD));
                    nData.add(new ME_Hover_2Type_Text("[" + CFG.getPercentageOld((Integer)tempSortedNum.get(i), tempTotalPop, 5) + "%]", CFG.COLOR_NEUTRAL));
                    nData.add(new ME_Hover_2Type_Text(" " + (CFG.getMetCiv((Integer)tempSortedNat.get(i)) ? CFG.core.getCiv((Integer)tempSortedNat.get(i)).getCivName() : CFG.lang.get("Undiscovered")), CFG.COLOR_TEXT_RANK_HOVER));
                    nElements.add(new MEHover_2E(nData));
                    nData.clear();
                }
            } else {
                for (i = 0; i < tempSortedNat.size(); ++i) {
                    nData.add(new ME_Hover_2Type_Flag((Integer)tempSortedNat.get(i)));
                    nData.add(new ME_Hover_2Type_Text("" + CFG.getNumberWthSpaces("" + tempSortedNum.get(i)), CFG.COLOR_POPULATION));
                    nData.add(new ME_Hover_2Type_Image(Images.pop, CFG.PADD, CFG.PADD));
                    nData.add(new ME_Hover_2Type_Text("[" + CFG.getPercentageOld((Integer)tempSortedNum.get(i), tempTotalPop, 5) + "%]", CFG.COLOR_NEUTRAL));
                    nData.add(new ME_Hover_2Type_Text(" " + CFG.core.getCiv((Integer)tempSortedNat.get(i)).getCivName(), CFG.COLOR_TEXT_RANK_HOVER));
                    nElements.add(new MEHover_2E(nData));
                    nData.clear();
                }
            }
            return new ME_Hover_v2(nElements);
        }
        catch (Exception ex) {
            return null;
        }
    }

    public static void MRPRV(int EOS) {
        try {
            for (int i = 0; i < AMRCT.size(); ++i) {
                if (Core.AMRCT.get((int)i).OBC != EOS) continue;
                if (AMRCT.size() > 1) {
                    AMRCT.remove(i);
                }
                return;
            }
            int RCTC = 0;
            for (int i = 0; i < AMRCT.size(); ++i) {
                if (CFG.core.getCiv(CFG.core.getProv(Core.AMRCT.get((int)i).OBC).getCivId()).isRAIP(Core.AMRCT.get((int)i).OBC) >= 0) continue;
                RCTC += CFG.ideologiesMgr.getIdeologyID((int)CFG.core.getCiv((int)CFG.core.getProv((int)Core.AMRCT.get((int)i).OBC).getCivId()).getIdeology()).COST_OF_RECRUIT;
            }
            if (CFG.core.getCiv(CFG.core.getProv(EOS).getCivId()).isRAIP(EOS) < 0) {
                RCTC += CFG.ideologiesMgr.getIdeologyID((int)CFG.core.getCiv((int)CFG.core.getProv((int)EOS).getCivId()).getIdeology()).COST_OF_RECRUIT;
            }
            if (AMRCT.isEmpty() || CFG.core.getCiv(CFG.core.getProv(EOS).getCivId()).isRAIP(EOS) >= 0 || CFG.core.getCiv(CFG.core.getProv(EOS).getCivId()).getMovemPoints() >= RCTC) {
                AMRCT.add(Core.RNDAR(EOS));
            } else {
                CFG.toastM.addM(CFG.lang.get("NoMovementPoints"), CFG.COLOR_NEGATIVE_1);
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

