    public final ME_Hover_v2 getHover_RankOfCiv(int nCivID) {
        try {
            ArrayList<MEHover_2E> nElements = new ArrayList<MEHover_2E>();
            ArrayList<ME_Hover_2Type> nData = new ArrayList<ME_Hover_2Type>();
            nData.add(new ME_Hover_2Type_Flag_Big(nCivID));
            nData.add(new ME_Hover_2Type_Text_Big(CFG.core.getCiv(nCivID).getCivName(), CFG.COLOR_HOVER_TITLE));
            nElements.add(new MEHover_2E(nData));
            nData.clear();
            nData.add(new ME_Hover_2Type_Space());
            nElements.add(new MEHover_2E(nData));
            nData.clear();
            nData.add(new ME_Hover_2Type_Text(CFG.lang.get("CivRank") + ": "));
            nData.add(new ME_Hover_2Type_Text("" + CFG.core.getCiv(nCivID).getRankPos() + "/" + CFG.core.getCivsSize(), CFG.COLOR_HOVER_TITLE));
            if (nCivID > 0) {
                nData.add(new ME_Hover_2Type_Image(CFG.getCivilizationRanking_IMG_STAR_CIVID(nCivID), CFG.PADD, 0));
            } else {
                nData.add(new ME_Hover_2Type_Image(Images.rank, CFG.PADD, 0));
            }
            nElements.add(new MEHover_2E(nData));
            nData.clear();
            nData.add(new ME_Hover_2Type_Text(CFG.lang.get("TotalScore") + ": "));
            nData.add(new ME_Hover_2Type_Text(CFG.getNumberWthSpaces("" + CFG.core.getCiv(nCivID).getRankScore()), CFG.COLOR_HOVER_TITLE));
            nData.add(new ME_Hover_2Type_Image(Images.rank, CFG.PADD, 0));
            nElements.add(new MEHover_2E(nData));
            nData.clear();
            nData.add(new ME_Hover_2Type_Graph(Graph2.GraphType.CIV_RANK, nCivID));
            nElements.add(new MEHover_2E(nData));
            nData.clear();
            return new ME_Hover_v2(nElements);
        }
        catch (Exception ex) {
            return null;
        }
    }

