    public final int getScenarioID() {
        return this.scenarioID;
    }

    public final void setScenarioID(int scenarioID) {
        this.scenarioID = scenarioID;
        try {
            this.gameScenarios.sActiveScenarioTag = this.gameScenarios.getScenarioTagID(this.getScenarioID());
        }
        catch (Exception ex) {
            this.gameScenarios.sActiveScenarioTag = "";
        }
    }

    public final void updateDaultScenarioID_ForMap() {
        int i = 0;
        while (true) {
            if (i >= Game_Scenarios.SCENARIOS_SIZE) break;
            if (this.gameScenarios.getScenarioTagID(i).equals(CFG.map.getMapDefaultScenario(CFG.map.getActiveMapIDN()))) {
                this.scenarioID = i;
                this.gameScenarios.sActiveScenarioTag = this.gameScenarios.getScenarioTagID(this.getScenarioID());
                break;
            }
            ++i;
        }
    }

    public final void whitePeace(int iCivA, int iCivB) {
        this.setCivRelationOfCivB(iCivA, iCivB, GameValues.gvDiplomacy.RELATION_WHITE_PEACE_AFTER);
        this.setCivRelationOfCivB(iCivB, iCivA, GameValues.gvDiplomacy.RELATION_WHITE_PEACE_AFTER);
    }

    public final void whitePeace_ReturnProvincesToRightfulOwners(int nCivA, int nCivB) {
        long nArmy0;
        int nProvinceID;
        int i;
        for (i = CFG.core.getCiv(nCivA).getNumOfProvs() - 1; i >= 0; --i) {
            if (CFG.core.getProv(CFG.core.getCiv(nCivA).getProvID(i)).getTrueOwnerOfProv() != nCivB) continue;
            nProvinceID = CFG.core.getCiv(nCivA).getProvID(i);
            nArmy0 = CFG.core.getProv(nProvinceID).getArmyCivID1(nCivA);
            CFG.core.getProv(nProvinceID).updateArmy4(nCivA, 0);
            CFG.core.getProv(nProvinceID).setCivId(nCivB, false, true);
            CFG.core.getProv(nProvinceID).updateArmy4(nCivA, nArmy0);
            CFG.gameAction.accessLost_MoveArmyToClosetsProvince(nCivA, nProvinceID);
        }
        for (i = CFG.core.getCiv(nCivB).getNumOfProvs() - 1; i >= 0; --i) {
            if (CFG.core.getProv(CFG.core.getCiv(nCivB).getProvID(i)).getTrueOwnerOfProv() != nCivA) continue;
            nProvinceID = CFG.core.getCiv(nCivB).getProvID(i);
            nArmy0 = CFG.core.getProv(nProvinceID).getArmyCivID1(nCivB);
            CFG.core.getProv(nProvinceID).updateArmy4(nCivB, 0);
            CFG.core.getProv(nProvinceID).setCivId(nCivA, false, true);
            CFG.core.getProv(nProvinceID).updateArmy4(nCivB, nArmy0);
            CFG.gameAction.accessLost_MoveArmyToClosetsProvince(nCivB, nProvinceID);
        }
    }

