    public final void war_CheckDiplomacy(int iAgressorCivID, int iCivB) {
        try {
            if (this.getCivNonAggressionPact(iAgressorCivID, iCivB) > 0) {
                this.setCivNonAggressionPact(iAgressorCivID, iCivB, 0);
            }
            if (this.getMilitaryAccess(iAgressorCivID, iCivB) > 0) {
                this.setMilitaryAccess(iAgressorCivID, iCivB, 0);
                CFG.gameAction.accessLost_UpdateArmies(iCivB, iAgressorCivID);
            }
            if (this.getMilitaryAccess(iCivB, iAgressorCivID) > 0) {
                this.setMilitaryAccess(iCivB, iAgressorCivID, 0);
                CFG.gameAction.accessLost_UpdateArmies(iAgressorCivID, iCivB);
            }
            if (this.getDefensivePact(iAgressorCivID, iCivB) > 0) {
                this.setDefensivePact(iAgressorCivID, iCivB, 0);
            }
            if (this.getGuarantee(iAgressorCivID, iCivB) > 0) {
                this.setGuarantee(iAgressorCivID, iCivB, 0);
            }
            if (this.getGuarantee(iCivB, iAgressorCivID) > 0) {
                this.setGuarantee(iCivB, iAgressorCivID, 0);
            }
            if (CFG.core.getCiv(iAgressorCivID).getPuppetOfCiv() == iCivB) {
                CFG.core.getCiv(iAgressorCivID).setPuppetOfCivId(iAgressorCivID);
                CFG.gameAction.accessLost_UpdateArmies(iCivB, iAgressorCivID);
                CFG.gameAction.accessLost_UpdateArmies(iAgressorCivID, iCivB);
                if (CFG.core.getCiv(iCivB).getIsPlayer()) {
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iCivB, iAgressorCivID);
                }
                if (CFG.core.getCiv(iAgressorCivID).getIsPlayer()) {
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iAgressorCivID, iCivB);
                }
            }
            if (CFG.core.getCiv(iCivB).getPuppetOfCiv() == iAgressorCivID) {
                CFG.core.getCiv(iCivB).setPuppetOfCivId(iCivB);
                CFG.gameAction.accessLost_UpdateArmies(iCivB, iAgressorCivID);
                CFG.gameAction.accessLost_UpdateArmies(iAgressorCivID, iCivB);
                if (CFG.core.getCiv(iCivB).getIsPlayer()) {
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iCivB, iAgressorCivID);
                }
                if (CFG.core.getCiv(iAgressorCivID).getIsPlayer()) {
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iAgressorCivID, iCivB);
                }
            }
            if (CFG.core.getCiv(iAgressorCivID).getAlliance() > 0 && CFG.core.getCiv(iAgressorCivID).getAlliance() == CFG.core.getCiv(iCivB).getAlliance()) {
                int tAllianceID = CFG.core.getCiv(iAgressorCivID).getAlliance();
                CFG.core.getAlliance(CFG.core.getCiv(iCivB).getAlliance()).removeCivilization(iCivB);
                CFG.core.getCiv(iCivB).setAlliance(0);
                CFG.core.getAlliance(CFG.core.getCiv(iAgressorCivID).getAlliance()).removeCivilization(iAgressorCivID);
                CFG.core.getCiv(iAgressorCivID).setAlliance(0);
                CFG.gameAction.accessLost_UpdateArmies(iCivB, iAgressorCivID);
                CFG.gameAction.accessLost_UpdateArmies(iAgressorCivID, iCivB);
                if (CFG.core.getCiv(iCivB).getIsPlayer()) {
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iCivB, iAgressorCivID);
                }
                if (CFG.core.getCiv(iAgressorCivID).getIsPlayer()) {
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iAgressorCivID, iCivB);
                }
                for (int i = 0; i < CFG.core.getAlliance(tAllianceID).getCivilizationsSize(); ++i) {
                    CFG.gameAction.accessLost_UpdateArmies(iCivB, CFG.core.getAlliance(tAllianceID).getCivilization(i));
                    CFG.gameAction.accessLost_UpdateArmies(CFG.core.getAlliance(tAllianceID).getCivilization(i), iCivB);
                    CFG.gameAction.accessLost_UpdateArmies(iAgressorCivID, CFG.core.getAlliance(tAllianceID).getCivilization(i));
                    CFG.gameAction.accessLost_UpdateArmies(CFG.core.getAlliance(tAllianceID).getCivilization(i), iAgressorCivID);
                    if (CFG.core.getCiv(iCivB).getIsPlayer()) {
                        this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iCivB, CFG.core.getAlliance(tAllianceID).getCivilization(i));
                    }
                    if (CFG.core.getCiv(iAgressorCivID).getIsPlayer()) {
                        this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(iAgressorCivID, CFG.core.getAlliance(tAllianceID).getCivilization(i));
                    }
                    if (!CFG.core.getCiv(CFG.core.getAlliance(tAllianceID).getCivilization(i)).getIsPlayer()) continue;
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(CFG.core.getAlliance(tAllianceID).getCivilization(i), iAgressorCivID);
                    this.war_CheckDiplomacy_AccessLost_UpdateFogOfWar(CFG.core.getAlliance(tAllianceID).getCivilization(i), iCivB);
                }
                this.checkAlliances();
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public final void war_CheckDiplomacy_AccessLost_UpdateFogOfWar(int nPlayerCivID, int inCivID) {
        try {
            int nPlayerID;
            if (CFG.FOG_OF_WAR > 0 && (nPlayerID = CFG.core.getPlayerIDbyCivID(nPlayerCivID)) >= 0) {
                int i;
                for (i = 0; i < CFG.core.getCiv(inCivID).getNumOfProvs(); ++i) {
                    CFG.core.getProv(CFG.core.getCiv(inCivID).getProvID(i)).updateFogOfWar(nPlayerID);
                    CFG.core.getProv(CFG.core.getCiv(inCivID).getProvID(i)).updateDrawArmyInProv();
                }
                for (i = 0; i < CFG.core.getCiv(inCivID).getArmyInAnotherProvinceSize(); ++i) {
                    CFG.core.getProv(CFG.core.getCiv(inCivID).getArmyInAnotherProviP(i)).updateFogOfWar(nPlayerID);
                    CFG.core.getProv(CFG.core.getCiv(inCivID).getArmyInAnotherProviP(i)).updateDrawArmyInProv();
                }
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

