    public final boolean isAtPeace(int nCivID) {
        int i;
        for (i = nCivID + 1; i < this.getCivsSize(); ++i) {
            if (this.getCiv(i).getNumOfProvs() <= 0 || (int)this.getCivRelationOfCivB(nCivID, i) != GameValues.gvDiplomacy.RELATION_AT_WAR) continue;
            return false;
        }
        for (i = nCivID - 1; i > 0; --i) {
            if (this.getCiv(i).getNumOfProvs() <= 0 || (int)this.getCivRelationOfCivB(nCivID, i) != GameValues.gvDiplomacy.RELATION_AT_WAR) continue;
            return false;
        }
        return true;
    }

    public final void moveCapitalToTheLargestCity(int nCivID) {
        if (CFG.core.getCiv(nCivID).getNumOfProvs() > 0) {
            int nLargestCity = CFG.core.getCiv(nCivID).getProvID(0);
            for (int i = 1; i < CFG.core.getCiv(nCivID).getNumOfProvs(); ++i) {
                if (CFG.core.getProv(CFG.core.getCiv(nCivID).getProvID(i)).getPop().getPops() <= CFG.core.getProv(nLargestCity).getPop().getPops()) continue;
                nLargestCity = CFG.core.getCiv(nCivID).getProvID(i);
            }
            CFG.core.getCiv(nCivID).setCapitalProvID(nLargestCity);
        }
    }

