    public final void setActiveProvID_Original(int nActiveProvinceID) {
        try {
            this.setActiveProv_ExtraAction.extraAction(nActiveProvinceID);
            if (this.iActiveProv >= 0) {
                int i;
                if (this.getProv(this.iActiveProv).getSeaProv()) {
                    for (i = 0; i < this.getProv(this.iActiveProv).getNeighProvincesSize(); ++i) {
                        if (this.iActiveProv < this.getProv(this.iActiveProv).getNeighProvinces(i)) {
                            if (this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getSeaProv()) {
                                this.getProv(this.iActiveProv).getProvBordersSeaBySea(this.getProv(this.iActiveProv).getNeighProvinces(i)).updateDrawProvinceBorderSeaBySea();
                                continue;
                            }
                            this.removeDrawProvinceBorder_LandBySea(this.iActiveProv, this.getProv(this.iActiveProv).getProvinceBordersLandBySea_ID(this.getProv(this.iActiveProv).getNeighProvinces(i)));
                            this.getProv(this.iActiveProv).getProvBordersLandBySea(this.getProv(this.iActiveProv).getNeighProvinces(i)).updateDrawProvinceBorder(this.iActiveProv);
                            continue;
                        }
                        if (this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getSeaProv()) {
                            this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvBordersSeaBySea(this.iActiveProv).updateDrawProvinceBorderSeaBySea();
                            continue;
                        }
                        this.removeDrawProvinceBorder_LandBySea(this.getProv(this.iActiveProv).getNeighProvinces(i), this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvinceBordersLandBySea_ID(this.iActiveProv));
                        this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvBordersLandBySea(this.iActiveProv).updateDrawProvinceBorder(this.getProv(this.iActiveProv).getNeighProvinces(i));
                    }
                } else {
                    for (i = 0; i < this.getProv(this.iActiveProv).getNeighProvincesSize(); ++i) {
                        if (this.iActiveProv < this.getProv(this.iActiveProv).getNeighProvinces(i)) {
                            if (this.getProv(this.iActiveProv).getProvBordersLandByLand(this.getProv(this.iActiveProv).getNeighProvinces(i)).getIsCivilizationBorder()) {
                                if (this.isActiveCivRegion_CivID(this.getProv(this.iActiveProv).getCivId(), this.getProv(this.iActiveProv).getCivRegionID())) {
                                    this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.iActiveProv).getCivId())).getRegionStyleID(this.getProv(this.iActiveProv).getCivRegionID())).updatePB(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                                    continue;
                                }
                                if (this.isActiveCivRegion_CivID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId(), this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())) {
                                    this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId())).getRegionStyleID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())).updatePB(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                                    continue;
                                }
                                this.getProv(this.iActiveProv).getProvBordersLandByLand(this.getProv(this.iActiveProv).getNeighProvinces(i)).updateDrawProvinceBorder(this.iActiveProv);
                                continue;
                            }
                            this.getProv(this.iActiveProv).getProvBordersLandByLand(this.getProv(this.iActiveProv).getNeighProvinces(i)).updateDrawProvinceBorder(this.iActiveProv);
                            continue;
                        }
                        if (this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvBordersLandByLand(this.iActiveProv).getIsCivilizationBorder()) {
                            if (this.isActiveCivRegion_CivID(this.getProv(this.iActiveProv).getCivId(), this.getProv(this.iActiveProv).getCivRegionID())) {
                                this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.iActiveProv).getCivId())).getRegionStyleID(this.getProv(this.iActiveProv).getCivRegionID())).updatePB(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                                continue;
                            }
                            if (this.isActiveCivRegion_CivID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId(), this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())) {
                                this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId())).getRegionStyleID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())).updatePB(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                                continue;
                            }
                            this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvBordersLandByLand(this.iActiveProv).updateDrawProvinceBorder(this.getProv(this.iActiveProv).getNeighProvinces(i));
                            continue;
                        }
                        this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvBordersLandByLand(this.iActiveProv).updateDrawProvinceBorder(this.getProv(this.iActiveProv).getNeighProvinces(i));
                    }
                }
            }
            int oldActiveProvinceID = this.iActiveProv;
            this.iActiveProv = nActiveProvinceID;
            this.activeProvAnimationData.resetAnimationData();
            if (oldActiveProvinceID >= 0) {
                this.getProv(oldActiveProvinceID).updateDrawArmyInProv();
            }
            if (this.iActiveProv >= 0) {
                this.getProv(this.iActiveProv).updateDrawArmyInProv();
                CFG.menus.getColorPicker().getColorPickerAction().setActiveProvince_Action();
            }
            if (CFG.menus.getInGameView()) {
                if (!CFG.chooseProvinceMode && !CFG.regroupArmyMode) {
                    this.checkProvinceActionMenu();
                }
                if (CFG.menus.getInGame_ProvincemMore_Visible()) {
                    if (this.getActiveProvID() < 0) {
                        CFG.menus.setVisible_InGame_ProvinceMore(false, false);
                    } else if (this.getActiveProvID() != oldActiveProvinceID) {
                        if (CFG.core.getProv(this.getActiveProvID()).getCivId() != CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId() && CFG.core.getCiv(CFG.core.getProv(this.getActiveProvID()).getCivId()).getPuppetOfCiv() != CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId()) {
                            CFG.menus.setVisible_InGame_ProvinceMore(false, false);
                        } else {
                            BuildingsManager.iBuildInProvinceID = this.getActiveProvID();
                            CFG.menus.setVisible_InGame_ProvinceMore(true, true);
                        }
                    }
                }
                if (CFG.mapModesManager.getActiveMapModeID() >= 0) {
                    CFG.mapModesManager.getActiveView().updateActiveProvinceID_ExtraAction(oldActiveProvinceID, this.getActiveProvID());
                }
                CFG.gameAction.updateInGame_ProvinceInfo();
            }
            if (CFG.isAndroid()) {
                CFG.menus.resetHoverActive();
            }
            this.lTIME_ACTIVE_CITIES = System.currentTimeMillis();
            if (this.iActiveProv >= 0) {
                if (this.getProv(this.iActiveProv).getSeaProv()) {
                    for (int i = 0; i < this.getProv(this.iActiveProv).getNeighProvincesSize(); ++i) {
                        if (this.iActiveProv < this.getProv(this.iActiveProv).getNeighProvinces(i)) {
                            if (this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getSeaProv()) {
                                this.activeProvinceBorder_SeaBySea_Style.update(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                                continue;
                            }
                            this.addDrawProvinceBorder_LandBySea(this.iActiveProv, this.getProv(this.iActiveProv).getProvinceBordersLandBySea_ID(this.getProv(this.iActiveProv).getNeighProvinces(i)));
                            this.activeProvinceBorder_LandBySea_Style.update(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                            continue;
                        }
                        if (this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getSeaProv()) {
                            this.activeProvinceBorder_SeaBySea_Style.update(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                            continue;
                        }
                        this.addDrawProvinceBorder_LandBySea(this.getProv(this.iActiveProv).getNeighProvinces(i), this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvinceBordersLandBySea_ID(this.iActiveProv));
                        this.activeProvinceBorder_LandBySea_Style.update(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                    }
                } else {
                    for (int i = 0; i < this.getProv(this.iActiveProv).getNeighProvincesSize(); ++i) {
                        if (this.iActiveProv < this.getProv(this.iActiveProv).getNeighProvinces(i)) {
                            if (this.getProv(this.iActiveProv).getProvBordersLandByLand(this.getProv(this.iActiveProv).getNeighProvinces(i)).getIsCivilizationBorder()) {
                                if (this.isActiveCivRegion_CivID(this.getProv(this.iActiveProv).getCivId(), this.getProv(this.iActiveProv).getCivRegionID())) {
                                    this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.iActiveProv).getCivId())).getRegionStyleID(this.getProv(this.iActiveProv).getCivRegionID())).updatePB(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                                    continue;
                                }
                                if (this.isActiveCivRegion_CivID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId(), this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())) {
                                    this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId())).getRegionStyleID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())).updatePB(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                                    continue;
                                }
                                this.activeProvinceBorder_LandByLand_Style.update(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                                continue;
                            }
                            this.activeProvinceBorder_LandByLand_Style.update(this.iActiveProv, this.getProv(this.iActiveProv).getNeighProvinces(i));
                            continue;
                        }
                        if (this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getProvBordersLandByLand(this.iActiveProv).getIsCivilizationBorder()) {
                            if (this.isActiveCivRegion_CivID(this.getProv(this.iActiveProv).getCivId(), this.getProv(this.iActiveProv).getCivRegionID())) {
                                this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.iActiveProv).getCivId())).getRegionStyleID(this.getProv(this.iActiveProv).getCivRegionID())).updatePB(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                                continue;
                            }
                            if (this.isActiveCivRegion_CivID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId(), this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())) {
                                this.lCivRegion_Styles.get(this.lActive_CivRegion.get(this.getCivRegionID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivId())).getRegionStyleID(this.getProv(this.getProv(this.iActiveProv).getNeighProvinces(i)).getCivRegionID())).updatePB(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                                continue;
                            }
                            this.activeProvinceBorder_LandByLand_Style.update(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                            continue;
                        }
                        this.activeProvinceBorder_LandByLand_Style.update(this.getProv(this.iActiveProv).getNeighProvinces(i), this.iActiveProv);
                    }
                }
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

