    public static void bCP(int i, String sLine) {
        try {
            int j;
            int pop = Integer.parseInt(sLine);
            float popGrowth = 0.0f;
            for (j = 0; j < CFG.core.getCiv(i).getNumOfProvs(); ++j) {
                popGrowth += CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getGrowthRate_Pop();
            }
            for (j = 0; j < CFG.core.getCiv(i).getNumOfProvs(); ++j) {
                Province_Population nProvince_Population;
                if (CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getPop().getNatsSize() <= 1) {
                    nProvince_Population = new Province_Population();
                    nProvince_Population.setPopulationOfCivID(i, (int)Math.max(1.0f, (float)pop * CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getGrowthRate_Pop() / popGrowth));
                    CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).setPopsData(nProvince_Population);
                    continue;
                }
                nProvince_Population = new Province_Population();
                for (int a = 0; a < CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getPop().getNatsSize(); ++a) {
                    nProvince_Population.setPopulationOfCivID(CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getPop().getCivID(a), (int)Math.max(1.0f, (float)pop * CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getGrowthRate_Pop() / popGrowth * ((float)CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getPop().getPopulationID(a) / (float)CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).getPop().getPops())));
                }
                CFG.core.getProv(CFG.core.getCiv(i).getProvID(j)).setPopsData(nProvince_Population);
            }
        }
        catch (Exception exception) {
            
        }
    }

