    public int festivalAllProvinces(int civID) {
        ArrayList<Integer> provinces = new ArrayList<Integer>();
        int out = 0;
        for (int i = 0; i < CFG.core.getCiv(civID).getNumOfProvs(); ++i) {
            if (CFG.core.getProv(CFG.core.getCiv(civID).getProvID(i)).isOccupied() || !(CFG.core.getProv(CFG.core.getCiv(civID).getProvID(i)).getHappi() < 1.0f) || CFG.core.getCiv(civID).isFestivalOrganized(CFG.core.getCiv(civID).getProvID(i))) continue;
            provinces.add(CFG.core.getCiv(civID).getProvID(i));
        }
        while (provinces.size() > 0 && CFG.core.getCiv(civID).getGold() > 0L) {
            int bestID = 0;
            for (int i = provinces.size() - 1; i > 0; --i) {
                if (!(CFG.core.getProv((Integer)provinces.get(bestID)).getHappi() > CFG.core.getProv((Integer)provinces.get(i)).getHappi())) continue;
                bestID = i;
            }
            if (!Festival.addFestival(civID, (Integer)provinces.get(bestID))) break;
            if (CFG.mapModesManager.getActiveMapModeID() == MapModesManager.VIEW_HAPPINESS_MODE) {
                CFG.core.getProv((int)((Integer)provinces.get((int)bestID)).intValue()).viewBool = true;
            }
            ++out;
            provinces.remove(bestID);
        }
        return out;
    }

