    public int fortAllProvinces(int civID) {
        ArrayList<Integer> provinces = new ArrayList<Integer>();
        int out = 0;
        int maxLVL = BuildingsManager.getFort_MaxLevel_CanBuild(civID);
        for (int i = 0; i < CFG.core.getCiv(civID).getNumOfProvs(); ++i) {
            int provinceID = CFG.core.getCiv(civID).getProvID(i);
            if (CFG.core.getProv(provinceID).isOccupied() || CFG.core.getProv(provinceID).getLvlOfFort() >= maxLVL || CFG.core.getCiv(civID).isInConstruction(provinceID, ConstructionType.FORT) != 0) continue;
            provinces.add(provinceID);
        }
        while (!provinces.isEmpty() && CFG.core.getCiv(civID).getGold() > 0L) {
            int bestID = 0;
            for (int i = provinces.size() - 1; i > 0; --i) {
                if (CFG.core.getProv((Integer)provinces.get(bestID)).getPop().getPops() >= CFG.core.getProv((Integer)provinces.get(i)).getPop().getPops()) continue;
                bestID = i;
            }
            if (!BuildingsManager.constructFort((Integer)provinces.get(bestID), civID)) break;
            ++out;
            provinces.remove(bestID);
        }
        if (out > 0) {
            CFG.menus.rebuildMenu_InGame_Infobox_AllAction(CFG.lang.get(BuildingsManager.getFort_Name(1)), CFG.lang.get("Provinces") + ": " + out, Images.infoBuild);
        } else {
            CFG.toastM.addM(CFG.lang.get(BuildingsManager.getFort_Name(1)) + ": " + CFG.lang.get("Provinces") + ": " + out, CFG.COLOR_TEXT_NUM_OF_PROVINCES);
            CFG.toastM.setTimeInView(2500);
        }
        CFG.menus.updateInGameTopAll(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId());
        return out;
    }

