    public boolean getPeaceTreaty_GameData_AlreadySent(int nCivA, int nCivB) {
        for (int i = this.lPeaceTreaties.size() - 1; i >= 0; --i) {
            for (int j = 0; j < this.lPeaceTreaties.get((int)i).peaceTreaty_GameData.civsDataDefenders.size(); ++j) {
                int k;
                if (this.lPeaceTreaties.get((int)i).peaceTreaty_GameData.civsDataDefenders.get((int)j).iCivID == nCivA) {
                    for (k = 0; k < this.lPeaceTreaties.get((int)i).peaceTreaty_GameData.civsDataAggressors.size(); ++k) {
                        if (this.lPeaceTreaties.get((int)i).peaceTreaty_GameData.civsDataAggressors.get((int)k).iCivID != nCivB) continue;
                        return true;
                    }
                    continue;
                }
                if (this.lPeaceTreaties.get((int)i).peaceTreaty_GameData.civsDataDefenders.get((int)j).iCivID != nCivB) continue;
                for (k = 0; k < this.lPeaceTreaties.get((int)i).peaceTreaty_GameData.civsDataAggressors.size(); ++k) {
                    if (this.lPeaceTreaties.get((int)i).peaceTreaty_GameData.civsDataAggressors.get((int)k).iCivID != nCivA) continue;
                    return true;
                }
            }
        }
        return false;
    }

    public final void addLoadArmiesWidth_ErrorIDs(int nProvinceID) {
        try {
            for (int i = this.loadArmiesWidth_ErrorIDs.size() - 1; i >= 0; --i) {
                if (this.loadArmiesWidth_ErrorIDs.get(i) != nProvinceID) continue;
                return;
            }
            this.loadArmiesWidth_ErrorIDs.add(nProvinceID);
        }
        catch (Exception exception) {
            
        }
    }

    public final void updateLoadArmiesWidth_ErrorIDs(SpriteBatch oSB) {
        for (int i = this.loadArmiesWidth_ErrorIDs.size() - 1; i >= 0; --i) {
            try {
                for (int j = 0; j < CFG.core.getProv(this.loadArmiesWidth_ErrorIDs.get(i)).getCivsSize(); ++j) {
                    CFG.core.getProv(this.loadArmiesWidth_ErrorIDs.get(i)).updateArmyWi(j);
                }
            }
            catch (Exception exception) {
                
            }
            this.loadArmiesWidth_ErrorIDs.remove(i);
        }
    }

    public static final Civilization_GameData3 loadCivilization(String nTag) {
        try {
            Civilization_GameData3 outCivData = loadCivilization_Path(nTag);
            if (outCivData != null) {
                return outCivData;
            }
            return new Civilization_GameData3();
        }
        catch (Exception exception) {
            return new Civilization_GameData3();
        }
    }

    private static final Civilization_GameData3 loadCivilization_Path(String nTag) {
        String[] paths = new String[]{
            "game/civilizations/" + nTag,
            "game/civilizations/" + CFG.ideologiesMgr.getRealTag(nTag),
            "game/civilizations_editor/" + nTag + "/" + nTag,
            "game/civilizations_editor/" + CFG.ideologiesMgr.getRealTag(nTag) + "/" + CFG.ideologiesMgr.getRealTag(nTag)
        };
        for (String path : paths) {
            try {
                FileHandle fileJSON = FileManager.loadFile(path + ".json");
                if (fileJSON.exists()) {
                    try {
                        Json json = new Json();
                        json.setIgnoreUnknownFields(true);
                        return json.fromJson(Civilization_GameData3.class, fileJSON.readString("UTF-8"));
                    }
                    catch (Exception ex) {
                        CFG.exceptionStack(ex);
                    }
                }
                FileHandle file = FileManager.loadFile(path);
                if (file.exists()) {
                    Civilization_GameData3 outCivData = (Civilization_GameData3)CFG.deserialize(file.readBytes());
                    try {
                        Json json = new Json();
                        json.setOutputType(JsonWriter.OutputType.json);
                        fileJSON.writeString(json.prettyPrint(outCivData), false, "UTF-8");
                    }
                    catch (Exception ex) {
                        
                    }
                    return outCivData;
                }
            }
            catch (Exception ex) {
                
            }
        }
        return null;
    }

    public static float getLineWidth3(float fromPosX, float fromPosY, float toPosX, float toPosY) {
        return (float)Math.sqrt(Math.pow(fromPosX - toPosX, 2.0) + Math.pow(fromPosY - toPosY, 2.0));
    }

    public static float getLinesAngle2(float fromPosX, float fromPosY, float toPosX, float toPosY) {
        return (float)(Math.atan2(fromPosY - toPosY, -fromPosX + toPosX) * 180.0 / Math.PI);
    }

    public static void bCP() {
        try {
            if (FileManager.loadFile("map/" + CFG.map.getFileActiveMapPath() + "scenarios/" + CFG.core.getGameScenars().getScenarioTagID(CFG.core.getScenarioID()) + "/pop.txt").exists()) {
                FileHandle file = FileManager.loadFile("map/" + CFG.map.getFileActiveMapPath() + "scenarios/" + CFG.core.getGameScenars().getScenarioTagID(CFG.core.getScenarioID()) + "/pop.txt");
                String text = file.readString();
                String[] lines = text.split("\\r?\\n");
                int lineID = 1;
                for (String line : lines) {
                    Core.bCP(lineID++, line);
                }
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public int pALPR(int civID) {
        ArrayList<Integer> provinces = new ArrayList<Integer>();
        int out = 0;
        int maxLVL = BuildingsManager.getPort_MaxLevel();
        for (int i = 0; i < CFG.core.getCiv(civID).getNumOfProvs(); ++i) {
            int provinceID = CFG.core.getCiv(civID).getProvID(i);
            if (CFG.core.getProv(provinceID).isOccupied() || CFG.core.getProv(provinceID).getNeighSeaProvincesSize() <= 0 || CFG.core.getProv(provinceID).getLvlOfPort() >= maxLVL || CFG.core.getCiv(civID).isInConstruction(provinceID, ConstructionType.PORT) != 0) continue;
            provinces.add(provinceID);
        }
        while (!provinces.isEmpty() && CFG.core.getCiv(civID).getGold() > 0L) {
            int bestID = 0;
            for (int i = provinces.size() - 1; i > 0; --i) {
                if (CFG.core.getProv((Integer)provinces.get(bestID)).getPop().getPops() >= CFG.core.getProv((Integer)provinces.get(i)).getPop().getPops()) continue;
                bestID = i;
            }
            if (!BuildingsManager.constructPort((Integer)provinces.get(bestID), civID)) break;
            ++out;
            provinces.remove(bestID);
        }
        if (out > 0) {
            CFG.menus.rebuildMenu_InGame_Infobox_AllAction(CFG.lang.get(BuildingsManager.getPort_Name(1)), CFG.lang.get("Provinces") + ": " + out, Images.infoBuild);
        } else {
            CFG.toastM.addM(CFG.lang.get(BuildingsManager.getPort_Name(1)) + ": " + CFG.lang.get("Provinces") + ": " + out, CFG.COLOR_TEXT_NUM_OF_PROVINCES);
            CFG.toastM.setTimeInView(2500);
        }
        CFG.menus.updateInGameTopAll(CFG.core.getPlayer(CFG.PLAYER_TURN_ID).getCivId());
        return out;
    }

