    public List<Integer> getPossibleUnions(int civID) {
        int i;
        ArrayList<Integer> out = new ArrayList<Integer>();
        for (i = 1; i < civID; ++i) {
            if (CFG.core.getCiv(i).getNumOfProvs() <= 0 || !AIPlaystyle.unionResponseAI(civID, i)) continue;
            out.add(i);
        }
        for (i = civID + 1; i < CFG.core.getCivsSize(); ++i) {
            if (CFG.core.getCiv(i).getNumOfProvs() <= 0 || !AIPlaystyle.unionResponseAI(civID, i)) continue;
            out.add(i);
        }
        return out;
    }

