    public static void drawMenuBG(SpriteBatch oSB, int posX, int posY, int width, int height) {
        if (CFG.settingsGD.BETTER_UI) {
            BetterUI_Manager.drawBetterMenuBG(oSB, posX, posY, width, height);
            return;
        }
        oSB.setColor(new Color(0.0f, 0.0f, 0.0f, 0.4f));
        IMGManager.getIMG(Images.gradientXYVertical).draw(oSB, (posX -= 2) - CFG.PADD * 2, posY, CFG.PADD * 2, height, true, false);
        IMGManager.getIMG(Images.gradientXYVertical).draw(oSB, posX + (width += 4), posY, CFG.PADD * 2, height);
        oSB.setColor(CFG.COLOR_GRADIENT_MENU_BLUE);
        IMGManager.getIMG(Images.pix255).draw(oSB, posX, posY, width, height);
        oSB.setColor(CFG.COLOR_GRADIENT_BLUE.r, CFG.COLOR_GRADIENT_BLUE.g, CFG.COLOR_GRADIENT_BLUE.b, 0.225f);
        IMGManager.getIMG(Images.line32Off1).draw(oSB, posX, posY, width, height);
        oSB.setColor(new Color(0.0f, 0.0f, 0.0f, 0.6f));
        IMGManager.getIMG(Images.gradient).draw(oSB, posX, posY, width, CFG.PADD * 3);
        IMGManager.getIMG(Images.gradient).draw(oSB, posX, posY + height - CFG.PADD * 3, width, CFG.PADD * 3, false, true);
        oSB.setColor(CFG.COLOR_CREATE_NEW_GAME_BOX_PLAYERS);
        IMGManager.getIMG(Images.pix255).draw(oSB, posX + 1, posY, 1, height);
        IMGManager.getIMG(Images.pix255).draw(oSB, posX + width - 2, posY, 1, height);
        oSB.setColor(0.0f, 0.0f, 0.0f, 0.325f);
        IMGManager.getIMG(Images.pix255).draw(oSB, posX, posY, 1, height);
        IMGManager.getIMG(Images.pix255).draw(oSB, posX + width - 1, posY, 1, height);
        oSB.setColor(Color.WHITE);
    }

    public void runAgeOfChaos() {
        try {
            if (!CFG.AGE_OF_CHAOS_MODE) {
                return;
            }
            if (GameCalendar.TURNID % CFG.AGE_OF_CHAOS_TURNS == 0) {
                if (CFG.SPECTATOR_MODE) {
                    return;
                }
                CFG.AGE_OF_CHAOS_CIVS_LIST.clear();
                ArrayList<Integer> civs = new ArrayList<Integer>();
                ArrayList<Integer> score = new ArrayList<Integer>();
                double k = 4.0;
                int currentPlayerCapital = Math.max(0, CFG.core.getCiv(CFG.core.getPlayer(0).getCivId()).getCapitalProvID() >= 0 ? CFG.core.getCiv(CFG.core.getPlayer(0).getCivId()).getCapitalProvID() : CFG.core.getCiv(CFG.core.getPlayer(0).getCivId()).getProvID(0));
                for (int i = 1; i < CFG.core.getCivsSize(); ++i) {
                    if (CFG.core.getCiv(i).getIsPlayer() || CFG.core.getCiv(i).getNumOfProvs() <= 0 || CFG.ideologiesMgr.getIdeologyID((int)CFG.core.getCiv((int)i).getIdeology()).REVOLUTIONARY) continue;
                    civs.add(i);
                    score.add((int)(10.0 + 1000.0 * Math.exp(-k * (double)Distance.getDistanceFromAToB_PercOfMax(currentPlayerCapital, Math.max(0, CFG.core.getCiv(i).getCapitalProvID())))));
                }
                if (!civs.isEmpty()) {
                    block3: for (int a = 0; a < CFG.AGE_OF_CHAOS_CIVS && !civs.isEmpty(); ++a) {
                        int totalScore = 0;
                        for (int i = score.size() - 1; i >= 0; --i) {
                            totalScore += ((Integer)score.get(i)).intValue();
                        }
                        int randomScore = CFG.oR.nextInt(totalScore);
                        int iSize = score.size();
                        int currentScore = 0;
                        for (int i = 0; i < iSize; ++i) {
                            if ((currentScore += ((Integer)score.get(i)).intValue()) < randomScore) continue;
                            CFG.AGE_OF_CHAOS_CIVS_LIST.add((Integer)civs.get(i));
                            civs.remove(i);
                            score.remove(i);
                            continue block3;
                        }
                    }
                    if (!CFG.AGE_OF_CHAOS_CIVS_LIST.isEmpty()) {
                        CFG.menus.setMenuIDWithoutAnim(View.eAGE_OF_CHAOS);
                    }
                }
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public static float getOverInvestmentsPenalty(int civID) {
        return CFG.core.getCiv((int)civID).civGD.numberOfInvestments * GameValues.gvOverInvestment.COST_INCREASE_PER_INVESTMENT;
    }

    public static void updateOverInvestment() {
        try {
            for (int i = 1 + GameCalendar.TURNID % GameValues.gvOverInvestment.UPDATE_EVERY_X_TURNS; i < CFG.core.getCivsSize(); i += GameValues.gvOverInvestment.UPDATE_EVERY_X_TURNS) {
                if (!(CFG.core.getCiv((int)i).civGD.numberOfInvestments > 0.0f)) continue;
                CFG.core.getCiv((int)i).civGD.numberOfInvestments = Math.max(0.0f, CFG.core.getCiv((int)i).civGD.numberOfInvestments - Math.max(GameValues.gvOverInvestment.UPDATE_DECAY_INVESTMENTS_FIXED_MIN, CFG.core.getCiv((int)i).civGD.numberOfInvestments * GameValues.gvOverInvestment.UPDATE_DECAY_INVESTMENTS__PERC));
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public final void savePopData() {
        try {
            if (CFG.getIsDesktop()) {
                FileHandle file = FileManager.IS_MAC ? Gdx.files.external("map/" + CFG.map.getFileActiveMapPath() + "scenarios/" + CFG.CREATE_SCENARIO_GAME_DATA_TAG + "/pop_template.txt") : Gdx.files.local("map/" + CFG.map.getFileActiveMapPath() + "scenarios/" + CFG.CREATE_SCENARIO_GAME_DATA_TAG + "/pop_template.txt");
                file.writeString(CFG.core.getCiv(1).getCivName() + "\n", false);
                for (int i = 2; i < CFG.core.getCivsSize(); ++i) {
                    file.writeString(CFG.core.getCiv(i).getCivName() + (i == CFG.core.getCivsSize() - 1 ? "" : "\n"), true);
                }
            }
        }
        catch (Exception ex) {
            CFG.exceptionStack(ex);
        }
    }

    public final void ceasefire(int civA, int civB) {
        int warID = this.getWarID(civA, civB);
        if (warID >= 0) {
            int b;
            int a;
            ArrayList<Integer> civsDef = new ArrayList<Integer>();
            ArrayList<Integer> civsAgg = new ArrayList<Integer>();
            for (a = 0; a < this.getWar(warID).getDefendersSize(); ++a) {
                civsDef.add(this.getWar(warID).getDefenderID(a).getCivID());
            }
            for (a = 0; a < this.getWar(warID).getAggressorsSize(); ++a) {
                civsAgg.add(this.getWar(warID).getAggressorID(a).getCivID());
            }
            for (a = civsDef.size() - 1; a >= 0; --a) {
                for (int z = 0; z < CFG.core.getCiv((Integer)civsDef.get(a)).getNumOfProvs(); ++z) {
                }
            }
            for (a = civsDef.size() - 1; a >= 0; --a) {
                for (b = civsAgg.size() - 1; b >= 0; --b) {
                    CFG.core.whitePeace((Integer)civsDef.get(a), (Integer)civsAgg.get(b));
                }
            }
            for (a = civsDef.size() - 1; a >= 0; --a) {
                for (b = civsAgg.size() - 1; b >= 0; --b) {
                    CFG.core.getCiv((int)((Integer)civsDef.get((int)a)).intValue()).civGD.civPlans.addNewWarPreps((Integer)civsDef.get(0), (Integer)civsDef.get(a), (Integer)civsAgg.get(b), GameValues.gvCeasefire.CEASEFIRE_TURNS);
                    CFG.core.getCiv((int)((Integer)civsAgg.get((int)b)).intValue()).civGD.civPlans.addNewWarPreps((Integer)civsAgg.get(0), (Integer)civsAgg.get(b), (Integer)civsDef.get(a), GameValues.gvCeasefire.CEASEFIRE_TURNS);
                }
            }
        }
    }

